'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s));
const sutras = [
 {id:'phap-cu',name:'Kinh Pháp Cú',pali:'Dhammapada · Tiểu Bộ Kinh',tag:'Lời dạy căn bản',group:'nen-tang',image:'assets/sutra-phap-cu.jpg',short:'Những bài kệ ngắn về tâm ý, hành động thiện lành và con đường sống tỉnh thức.',source:'https://suttacentral.net/dhp',sections:[
  ['Giới thiệu','Kinh Pháp Cú (Dhammapada) gồm 423 bài kệ, được xếp trong Tiểu Bộ Kinh. Những câu kệ cô đọng giúp người đọc soi lại lời nói, hành vi và ý nghĩ trong đời sống thường nhật.'],
  ['Diễn ý để suy ngẫm','Tâm ý định hướng lời nói và hành động. Khi ta nuôi dưỡng một tâm lành, cách ta nhìn cuộc đời và ứng xử với người khác cũng có cơ hội chuyển hóa.','Một người biết dừng lại trước cơn giận, biết nói lời chân thật và làm điều thiện đang tạo ra những điều kiện cho bình an lớn lên.'],
  ['Gợi ý thực tập','Hôm nay, trước khi trả lời một câu nói làm mình khó chịu, hãy tạm dừng ba hơi thở. Hãy tự hỏi: “Lời này có thật, có cần thiết và có đem lại điều lành không?”']
 ]},
 {id:'tu-bi',name:'Kinh Từ Bi',pali:'Karaṇīya Mettā Sutta · Snp 1.8',tag:'Nuôi dưỡng yêu thương',group:'tu-bi',image:'assets/sutra-tu-bi.jpg',short:'Học cách mở rộng lòng từ, mong cho mình và mọi chúng sinh được an vui.',source:'https://suttacentral.net/snp1.8/vi/minh_chau',sections:[
  ['Giới thiệu','Kinh Từ Bi thuộc Kinh Tập (Sutta Nipāta 1.8), hướng người tu tập đến đời sống chân thật, khiêm nhu, biết đủ và nuôi dưỡng tâm từ không giới hạn.'],
  ['Diễn ý để suy ngẫm','Hãy bắt đầu bằng ước nguyện bình an dành cho chính mình. Rồi mở rộng ước nguyện ấy đến người thương, người chưa hiểu mình và tất cả sinh linh.','Lòng từ không phải là đòi hỏi mọi người phải giống ý ta. Đó là mong người khác giảm khổ và được sống an ổn, ngay cả khi còn khác biệt.'],
  ['Gợi ý thực tập','Ngồi yên trong một phút, thầm nhắc: “Mong tôi được bình an. Mong người thân được bình an. Mong mọi loài được bình an.”']
 ]},
 {id:'chuyen-phap-luan',name:'Kinh Chuyển Pháp Luân',pali:'Dhammacakkappavattana Sutta · SN 56.11',tag:'Tứ Diệu Đế',group:'nen-tang',image:'assets/sutra-chuyen-phap-luan.jpg',short:'Tìm hiểu con đường Trung đạo và bốn sự thật cao quý trong giáo lý Đức Phật.',source:'https://suttacentral.net/sn56.11',sections:[
  ['Giới thiệu','Kinh Chuyển Pháp Luân (SN 56.11) trình bày con đường Trung đạo, Tứ Diệu Đế và Bát Chánh Đạo. Đây là một bài kinh nền tảng để bắt đầu tìm hiểu giáo lý Phật giáo.'],
  ['Diễn ý để suy ngẫm','Có những bất toại nguyện trong cuộc sống. Thay vì né tránh hay đổ lỗi, ta học cách nhận ra chúng, thấy những nguyên nhân nuôi dưỡng chúng và khả năng chuyển hóa.','Con đường thực tập không phải buông xuôi hay ép xác. Đó là học nhìn đúng, nghĩ đúng, nói đúng, làm đúng và nuôi dưỡng sự chú tâm trong từng bước.'],
  ['Gợi ý thực tập','Khi gặp một điều phiền muộn, hãy viết ra ba câu: “Điều gì đang làm tôi khổ?”, “Điều gì đang nuôi lớn nỗi khổ ấy?”, “Tôi có thể thay đổi một việc nhỏ nào hôm nay?”']
 ]},
 {id:'niem-xu',name:'Kinh Niệm Xứ',pali:'Satipaṭṭhāna Sutta · MN 10',tag:'Thiền quán',group:'chanh-niem',image:'assets/sutra-niem-xu.jpg',short:'Thực tập quán sát thân, cảm thọ, tâm và các pháp một cách rõ biết.',source:'https://suttacentral.net/mn10',sections:[
  ['Giới thiệu','Kinh Niệm Xứ (MN 10) trình bày bốn lĩnh vực quán niệm: thân, cảm thọ, tâm và các pháp. Trọng tâm là nhận biết rõ điều đang diễn ra mà không vội đồng nhất mình với nó.'],
  ['Diễn ý để suy ngẫm','Khi đi, biết mình đang đi. Khi ngồi, biết mình đang ngồi. Khi vui hay buồn, biết có niềm vui hay nỗi buồn đang hiện diện.','Nhờ thấy rõ những thay đổi của thân và tâm, ta bớt bị cuốn vào phản ứng tự động và có thêm không gian để lựa chọn cách ứng xử.'],
  ['Gợi ý thực tập','Trong năm phút, chọn một việc rất thường ngày như rửa tay hoặc uống trà. Chú ý cảm giác nơi thân, hơi thở và dòng suy nghĩ đang đi qua.']
 ]},
 {id:'nhap-tuc-xuat-tuc',name:'Kinh Nhập tức, Xuất tức niệm',pali:'Ānāpānasati Sutta · MN 118',tag:'Chánh niệm hơi thở',group:'chanh-niem',image:'assets/sutra-hoi-tho.jpg',short:'Lấy hơi thở làm điểm tựa để an trú và phát triển chánh niệm.',source:'https://suttacentral.net/mn118',sections:[
  ['Giới thiệu','Kinh Nhập tức, Xuất tức niệm (MN 118), còn gọi là Kinh Quán niệm hơi thở, hướng dẫn sự thực tập chánh niệm dựa trên hơi thở vào và hơi thở ra.'],
  ['Diễn ý để suy ngẫm','Không cần làm cho hơi thở phải dài hay ngắn theo ý muốn. Bắt đầu bằng việc nhận biết chính xác hơi thở đang diễn ra thế nào.','Cảm nhận toàn thân, buông bớt căng thẳng, thấy tâm đang chuyển động và đưa sự tỉnh thức trở lại trong mỗi chu kỳ thở.'],
  ['Gợi ý thực tập','Ngồi thoải mái. Trong một phút, thầm biết “đang hít vào” khi hít vào và “đang thở ra” khi thở ra. Khi tâm đi xa, chỉ nhẹ nhàng trở về.']
 ]},
 {id:'hanh-phuc',name:'Kinh Hạnh Phúc',pali:'Maṅgala Sutta · Snp 2.4',tag:'Sống thiện lành',group:'tu-bi',image:'assets/sutra-hanh-phuc.jpg',short:'Những điều lành nên vun bồi để xây dựng đời sống có ý nghĩa và an ổn.',source:'https://suttacentral.net/snp2.4',sections:[
  ['Giới thiệu','Kinh Hạnh Phúc (Snp 2.4) giới thiệu những điều lành trong nếp sống: biết chọn môi trường tốt, học hỏi, hiếu kính, giữ đạo đức và phát triển trí tuệ.'],
  ['Diễn ý để suy ngẫm','Hạnh phúc không chỉ đến từ may mắn bên ngoài. Nó được nuôi dưỡng bằng những lựa chọn hằng ngày: tôn trọng người khác, biết ơn người thân và sống có trách nhiệm.','Khi đời sống gặp biến động, một tâm được rèn luyện có thể vững vàng hơn trước khen chê, được mất, thuận nghịch.'],
  ['Gợi ý thực tập','Tối nay, hãy ghi lại một việc thiện bạn đã làm, một người bạn muốn cảm ơn và một thói quen tốt bạn muốn tiếp tục.']
 ]}
];
sutras.push(...[{"id":"sang-binh-an","name":"Thời kinh buổi sáng – Khởi đầu an lành","pali":"Nghi thức gợi ý · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"hang-ngay","topics":["hang-ngay"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Một trình tự ngắn để quy hướng tâm, đọc kinh và phát nguyện khi bắt đầu ngày mới.","intro":"Đây là trình tự thực tập do Gió Lành gợi ý, không phải một bài kinh độc lập được ghi trong Tam tạng. Có thể kết hợp quy y, một đoạn kinh ngắn và hồi hướng theo truyền thống của gia đình.","source":"https://www.thuvienhoasen.org/","sourceLabel":"Tra cứu nguồn tham khảo","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Đây là trình tự thực tập do Gió Lành gợi ý, không phải một bài kinh độc lập được ghi trong Tam tạng. Có thể kết hợp quy y, một đoạn kinh ngắn và hồi hướng theo truyền thống của gia đình."],["Nội dung và ý nghĩa","Đặt tâm ngay thẳng, đọc chậm, nuôi ý nguyện không hại người và mở lòng với những việc thiện trong ngày."],["Gợi ý đọc và thực hành","Trước khi bắt đầu công việc, ngồi yên ba hơi thở, đọc Kinh Hạnh Phúc hoặc Kinh Từ Bi, rồi hồi hướng điều lành."]]},{"id":"toi-lang-tam","name":"Thời kinh buổi tối – Nhìn lại một ngày","pali":"Nghi thức gợi ý · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"truoc-ngu","topics":["truoc-ngu","hang-ngay"],"image":"assets/sutra-hanh-phuc.jpg","short":"Lời nhắc buông bớt phiền muộn, nhìn lại việc làm trong ngày và ngủ với tâm nhẹ.","intro":"Đây là thời khóa gợi ý do Gió Lành biên soạn, không phải nguyên văn kinh Phật. Một thời kinh tối có thể gồm sám hối, đọc một đoạn kinh phù hợp, niệm Phật và hồi hướng.","source":"https://www.thuvienhoasen.org/","sourceLabel":"Tra cứu nguồn tham khảo","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Đây là thời khóa gợi ý do Gió Lành biên soạn, không phải nguyên văn kinh Phật. Một thời kinh tối có thể gồm sám hối, đọc một đoạn kinh phù hợp, niệm Phật và hồi hướng."],["Nội dung và ý nghĩa","Nhìn lại ngày sống với sự chân thật, nhận biết điều lành đã làm và những điều cần sửa đổi mà không tự trách móc quá mức."],["Gợi ý đọc và thực hành","Tắt bớt màn hình, thở tự nhiên một phút, đọc lời nguyện tối và hồi hướng trước khi nghỉ."]]},{"id":"niem-phat-truoc-ngu","name":"Niệm Phật trước khi ngủ","pali":"Pháp môn Tịnh độ · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"truoc-ngu","topics":["truoc-ngu","hang-ngay"],"image":"assets/sutra-tu-bi.jpg","short":"Thực tập niệm danh hiệu Phật A Di Đà với tâm chú ý và kính trọng.","intro":"Niệm Phật trước khi ngủ là phương thức hành trì phổ biến trong truyền thống Tịnh độ, không phải một bài kinh mang tên độc lập. Người thực tập có thể niệm thầm hoặc niệm nhỏ theo hơi thở.","source":"https://www.thuvienhoasen.org/","sourceLabel":"Tra cứu nguồn tham khảo","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Niệm Phật trước khi ngủ là phương thức hành trì phổ biến trong truyền thống Tịnh độ, không phải một bài kinh mang tên độc lập. Người thực tập có thể niệm thầm hoặc niệm nhỏ theo hơi thở."],["Nội dung và ý nghĩa","Nương vào danh hiệu Phật để gom tâm và hướng về phẩm hạnh từ bi, chánh niệm và tinh tấn."],["Gợi ý đọc và thực hành","Niệm chậm “Nam mô A Di Đà Phật” theo số lần vừa sức; nếu buồn ngủ, nghỉ ngơi tự nhiên."]]},{"id":"tu-bi-truoc-ngu","name":"Quán tâm từ trước khi ngủ","pali":"Gợi ý theo Snp 1.8 · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"truoc-ngu","topics":["truoc-ngu","hang-ngay"],"image":"assets/sutra-hoi-tho.jpg","short":"Dành ít phút gửi lời chúc an vui đến bản thân, gia đình và muôn loài.","intro":"Bài thực tập này lấy cảm hứng từ Kinh Từ Bi, không phải trích nguyên văn bản dịch kinh. Trước giấc ngủ, hành giả có thể khơi dậy thái độ không oán hận và thiện ý.","source":"https://suttacentral.net/snp1.8","sourceLabel":"Tra cứu nguồn tham khảo","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Bài thực tập này lấy cảm hứng từ Kinh Từ Bi, không phải trích nguyên văn bản dịch kinh. Trước giấc ngủ, hành giả có thể khơi dậy thái độ không oán hận và thiện ý."],["Nội dung và ý nghĩa","Tâm từ không đòi hỏi phải có cảm xúc đặc biệt; đó là sự hướng tâm mong giảm khổ cho mình và người."],["Gợi ý đọc và thực hành","Thầm nguyện: “Mong tôi được bình an; mong những người tôi gặp được bình an; mong mọi loài được an vui.”"]]},{"id":"hoi-huong-cong-duc","name":"Bài kệ hồi hướng công đức","pali":"Kệ tụng trong nghi thức · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"hoi-huong","topics":["hoi-huong","hang-ngay","truoc-ngu"],"image":"assets/sutra-tu-bi.jpg","short":"Hướng điều thiện đã làm đến lợi ích của tất cả chúng sinh.","intro":"Hồi hướng là phần thường gặp ở cuối thời tụng niệm trong nhiều truyền thống Phật giáo. Văn kệ và thứ tự tụng có nhiều dị bản; đây là phần giới thiệu và lời nguyện mẫu, không gán cho một bản kinh riêng.","source":"https://phatgiao.org.vn/hoi-huong-cong-duc--cach-thuc-va-hieu-qua-d102649.html","sourceLabel":"Tra cứu nguồn tham khảo","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Hồi hướng là phần thường gặp ở cuối thời tụng niệm trong nhiều truyền thống Phật giáo. Văn kệ và thứ tự tụng có nhiều dị bản; đây là phần giới thiệu và lời nguyện mẫu, không gán cho một bản kinh riêng."],["Nội dung và ý nghĩa","Hồi hướng nhắc người thực tập không giữ điều thiện cho riêng mình mà mở lòng mong tất cả bớt khổ, thêm vui."],["Gợi ý đọc và thực hành","Lời nguyện gợi ý: “Nguyện những điều lành con đã làm hôm nay trở thành duyên cho hiểu biết và lòng từ bi lớn lên. Nguyện mọi người được bình an, biết thương nhau và cùng tiến trên đường thiện.”"]]},{"id":"hoi-huong-ong-ba","name":"Hồi hướng đến ông bà, cha mẹ và người thân","pali":"Nghi thức tưởng niệm · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"hoi-huong","topics":["hoi-huong","truoc-ngu"],"image":"assets/sutra-hanh-phuc.jpg","short":"Tưởng nhớ ân nghĩa người thân và hướng phước lành bằng tâm biết ơn.","intro":"Đây là lời hồi hướng thực tập, không phải bản kinh riêng biệt. Nhiều gia đình dùng thời tụng niệm để nuôi dưỡng lòng hiếu kính với cha mẹ, tổ tiên và người thân đã khuất.","source":"https://www.thuvienhoasen.org/","sourceLabel":"Tra cứu nguồn tham khảo","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Đây là lời hồi hướng thực tập, không phải bản kinh riêng biệt. Nhiều gia đình dùng thời tụng niệm để nuôi dưỡng lòng hiếu kính với cha mẹ, tổ tiên và người thân đã khuất."],["Nội dung và ý nghĩa","Tưởng nhớ không chỉ là lời cầu nguyện mà còn là sống có đạo đức, chăm sóc người còn bên mình và làm điều ích lợi."],["Gợi ý đọc và thực hành","Lời nguyện gợi ý: “Nguyện những việc thiện con làm hôm nay là duyên lành để biết ơn và báo đáp công lao sinh thành, dưỡng dục; mong người thân hiện tiền và đã khuất đều được an lành theo nhân duyên.”"]]},{"id":"hoi-huong-chung-sinh","name":"Hồi hướng đến tất cả chúng sinh","pali":"Nghi thức hồi hướng · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"hoi-huong","topics":["hoi-huong","hang-ngay"],"image":"assets/sutra-niem-xu.jpg","short":"Mở rộng tâm nguyện hướng đến mọi loài không phân biệt thân sơ.","intro":"Lời hồi hướng này được biên soạn làm ví dụ thực tập, phù hợp đọc cuối thời kinh. Các nghi thức Phật giáo có thể dùng nhiều bản kệ khác nhau tùy truyền thống.","source":"https://www.thuvienhoasen.org/","sourceLabel":"Tra cứu nguồn tham khảo","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Lời hồi hướng này được biên soạn làm ví dụ thực tập, phù hợp đọc cuối thời kinh. Các nghi thức Phật giáo có thể dùng nhiều bản kệ khác nhau tùy truyền thống."],["Nội dung và ý nghĩa","Tập nhìn rộng hơn nhu cầu cá nhân, mong các hữu tình được nương nhờ những điều kiện tốt đẹp và giảm bớt khổ đau."],["Gợi ý đọc và thực hành","Nguyện điều thiện được lan tỏa trong gia đình, cộng đồng và đến mọi chúng sinh."]]},{"id":"sam-hoi-buoi-toi","name":"Sám hối cuối ngày","pali":"Nghi thức sám hối · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"truoc-ngu","topics":["truoc-ngu","hang-ngay"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Nhận lỗi, học sửa lỗi và phát nguyện không lặp lại hành động gây hại.","intro":"Sám hối là thực hành nhận biết điều chưa thiện và quyết tâm sửa đổi, có nhiều bài văn sám khác nhau trong truyền thống Phật giáo. Mục này là gợi ý thực tập chứ không thay thế nghi thức của chùa.","source":"https://www.thuvienhoasen.org/","sourceLabel":"Tra cứu nguồn tham khảo","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Sám hối là thực hành nhận biết điều chưa thiện và quyết tâm sửa đổi, có nhiều bài văn sám khác nhau trong truyền thống Phật giáo. Mục này là gợi ý thực tập chứ không thay thế nghi thức của chùa."],["Nội dung và ý nghĩa","Sám hối có ý nghĩa khi đi cùng việc sửa sai cụ thể, xin lỗi khi phù hợp và nuôi dưỡng hành vi tốt."],["Gợi ý đọc và thực hành","Nhìn lại một lời nói hoặc hành động chưa phù hợp hôm nay, nhận trách nhiệm và chọn một cách sửa đổi vào ngày mai."]]},{"id":"tam-quy-y","name":"Tam quy y","pali":"Nghi thức quy y Tam bảo · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"hang-ngay","topics":["hang-ngay"],"image":"assets/sutra-phap-cu.jpg","short":"Nhắc nhớ nương tựa Phật, Pháp và Tăng khi tu học.","intro":"Tam quy y là nền tảng của đời sống Phật tử, quy hướng về bậc giác ngộ, giáo pháp và cộng đồng tu học chân chánh. Các bản tụng Việt có thể khác nhau theo nghi thức.","source":"https://www.thuvienhoasen.org/","sourceLabel":"Tra cứu nguồn tham khảo","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Tam quy y là nền tảng của đời sống Phật tử, quy hướng về bậc giác ngộ, giáo pháp và cộng đồng tu học chân chánh. Các bản tụng Việt có thể khác nhau theo nghi thức."],["Nội dung và ý nghĩa","Quy y không chỉ là lời tụng, mà còn là định hướng học hỏi và thực hành trí tuệ, từ bi, giới hạnh."],["Gợi ý đọc và thực hành","Đọc chậm từng nội dung quy y và tự hỏi hôm nay mình có thể sống đúng với sự nương tựa ấy như thế nào."]]},{"id":"ngu-gioi","name":"Năm giới của người cư sĩ","pali":"Giới học căn bản · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"hang-ngay","topics":["hang-ngay"],"image":"assets/sutra-niem-xu.jpg","short":"Tìm hiểu năm nguyên tắc đạo đức căn bản trong đời sống tại gia.","intro":"Năm giới là nền tảng thực tập đạo đức của người Phật tử tại gia, thường được nhắc lại trong các thời khóa. Đây là nội dung giới học, không phải một bài kinh độc lập mang cùng tên.","source":"https://www.thuvienhoasen.org/","sourceLabel":"Tra cứu nguồn tham khảo","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Năm giới là nền tảng thực tập đạo đức của người Phật tử tại gia, thường được nhắc lại trong các thời khóa. Đây là nội dung giới học, không phải một bài kinh độc lập mang cùng tên."],["Nội dung và ý nghĩa","Tránh sát hại, trộm cắp, tà hạnh, nói dối và các chất say gây phóng dật là cách xây dựng niềm tin và an toàn cho cộng đồng."],["Gợi ý đọc và thực hành","Chọn một giới để quán chiếu thật cụ thể trong sinh hoạt hôm nay."]]},{"id":"bon-loi-nguyen-lon","name":"Bốn lời nguyện rộng lớn","pali":"Tứ hoằng thệ nguyện · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"hang-ngay","topics":["hang-ngay","hoi-huong"],"image":"assets/sutra-tu-bi.jpg","short":"Phát nguyện học pháp, chuyển hóa phiền não và giúp đỡ chúng sinh.","intro":"Tứ hoằng thệ nguyện là bốn lời phát nguyện quen thuộc trong nghi lễ Đại thừa, được diễn đạt khác nhau giữa các truyền thống. Đây là lời nguyện tu học, không phải toàn văn một bài kinh.","source":"https://www.thuvienhoasen.org/","sourceLabel":"Tra cứu nguồn tham khảo","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Tứ hoằng thệ nguyện là bốn lời phát nguyện quen thuộc trong nghi lễ Đại thừa, được diễn đạt khác nhau giữa các truyền thống. Đây là lời nguyện tu học, không phải toàn văn một bài kinh."],["Nội dung và ý nghĩa","Các lời nguyện giúp người thực tập giữ hướng đi lâu dài: thương người, học hỏi, chuyển hóa thói quen bất thiện, hướng đến giác ngộ."],["Gợi ý đọc và thực hành","Chọn một lời nguyện và liên hệ với một hành động thiết thực trong ngày."]]},{"id":"bat-nha-buoi-toi","name":"Tụng Bát Nhã Tâm Kinh buổi tối","pali":"T0251 · Nghi thức thực tập","tag":"Nghi thức thực tập","group":"truoc-ngu","topics":["truoc-ngu","hang-ngay"],"image":"assets/sutra-tu-bi.jpg","short":"Thời khóa gợi ý sử dụng Tâm Kinh để quán chiếu tính duyên sinh và buông chấp.","intro":"Đây là hướng dẫn sắp xếp thời khóa trước khi ngủ, không phải một bản kinh khác với Bát Nhã Tâm Kinh. Nội dung kinh gốc được tra cứu tại CBETA, mã T0251.","source":"https://cbetaonline.dila.edu.tw/zh/T0251","sourceLabel":"Tham khảo kinh bản gốc","kind":"nghi","sections":[["Giới thiệu về bài nghi thức","Đây là hướng dẫn sắp xếp thời khóa trước khi ngủ, không phải một bản kinh khác với Bát Nhã Tâm Kinh. Nội dung kinh gốc được tra cứu tại CBETA, mã T0251."],["Nội dung và ý nghĩa","Sự quán chiếu trí tuệ giúp giảm bớt chấp trước và tạo không gian cho tâm nghỉ ngơi."],["Gợi ý đọc và thực hành","Đọc bản Tâm Kinh theo truyền thống mình đang học, ngồi yên đôi phút rồi hồi hướng."]]},{"id":"chu-dai-bi","name":"Chú Đại Bi","pali":"T1060 · Chú / Đà-la-ni","tag":"Chú / Đà-la-ni","group":"chu","topics":["chu","hang-ngay","truoc-ngu"],"image":"assets/sutra-phap-cu.jpg","short":"Đại Bi Tâm Đà-la-ni gắn với hạnh nguyện cứu khổ của Bồ Tát Quán Thế Âm.","intro":"Chú Đại Bi thuộc hệ thống Đại Bi Tâm Đà-la-ni và có bản kinh liên quan mang mã Đại Chánh tạng T1060. Trong thực hành Việt Nam có nhiều cách phiên âm; người tụng nên chọn bản do đạo tràng hoặc cơ sở Phật giáo tin cậy sử dụng.","source":"https://cbetaonline.dila.edu.tw/zh/T1060","sourceLabel":"Tham khảo kinh bản gốc","kind":"chu","sections":[["Giới thiệu về bài chú","Chú Đại Bi thuộc hệ thống Đại Bi Tâm Đà-la-ni và có bản kinh liên quan mang mã Đại Chánh tạng T1060. Trong thực hành Việt Nam có nhiều cách phiên âm; người tụng nên chọn bản do đạo tràng hoặc cơ sở Phật giáo tin cậy sử dụng."],["Nội dung và ý nghĩa","Tâm từ bi và ý nguyện cứu khổ là trọng tâm của sự hành trì. Chú là âm phiên truyền thống, không thể thay bằng bản diễn nghĩa tự do rồi gọi đó là nguyên văn."],["Gợi ý đọc và thực hành","Đối chiếu bản chú trong nghi thức đang tu học; giữ tâm cung kính, đọc đúng theo bản đã chọn và hồi hướng."]]},{"id":"chu-lang-nghiem","name":"Chú Lăng Nghiêm","pali":"Liên hệ Kinh Thủ Lăng Nghiêm (T0945) · Chú","tag":"Chú / Đà-la-ni","group":"chu","topics":["chu","hang-ngay"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Một đà-la-ni dài gắn với truyền thống tụng Kinh Thủ Lăng Nghiêm.","intro":"Chú Lăng Nghiêm được truyền tụng trong nhiều thời khóa Phật giáo Bắc truyền và thường đặt trong mối liên hệ với Kinh Thủ Lăng Nghiêm. Văn bản rất dài, có dị bản phiên âm.","source":"https://cbetaonline.dila.edu.tw/zh/T0945","sourceLabel":"Tham khảo kinh bản gốc","kind":"chu","sections":[["Giới thiệu về bài chú","Chú Lăng Nghiêm được truyền tụng trong nhiều thời khóa Phật giáo Bắc truyền và thường đặt trong mối liên hệ với Kinh Thủ Lăng Nghiêm. Văn bản rất dài, có dị bản phiên âm."],["Nội dung và ý nghĩa","Giữ tâm cung kính, bền bỉ và học hỏi sự thực hành giới, định, tuệ đi cùng việc tụng chú."],["Gợi ý đọc và thực hành","Không lấy giọng máy đọc diễn ý thay cho tụng chú; nên học âm đọc từ khóa lễ được hướng dẫn."]]},{"id":"luc-tu-dai-minh","name":"Lục Tự Đại Minh Chân Ngôn","pali":"Om Mani Padme Hum · Chú / Đà-la-ni","tag":"Chú / Đà-la-ni","group":"chu","topics":["chu","hang-ngay","truoc-ngu"],"image":"assets/sutra-niem-xu.jpg","short":"Chân ngôn sáu âm gắn với Bồ Tát Quán Thế Âm trong nhiều truyền thống.","intro":"Lục Tự Đại Minh Chân Ngôn thường được đọc là “Om Mani Padme Hum”, đặc biệt phổ biến trong Phật giáo Tây Tạng và có mặt trong truyền thống Đại thừa. Đây là chân ngôn chứ không phải một bài kinh độc lập.","source":"https://www.thuvienhoasen.org/","sourceLabel":"Tra cứu nguồn tham khảo","kind":"chu","sections":[["Giới thiệu về bài chú","Lục Tự Đại Minh Chân Ngôn thường được đọc là “Om Mani Padme Hum”, đặc biệt phổ biến trong Phật giáo Tây Tạng và có mặt trong truyền thống Đại thừa. Đây là chân ngôn chứ không phải một bài kinh độc lập."],["Nội dung và ý nghĩa","Nhắc người thực tập nuôi dưỡng lòng bi mẫn và chú tâm thay vì chỉ đếm số lần trì tụng."],["Gợi ý đọc và thực hành","Nếu muốn thực hành bài bản, nên theo truyền thống của người hướng dẫn và giữ lòng tôn trọng các cách phát âm."]]},{"id":"chu-chuan-de","name":"Chú Chuẩn Đề","pali":"Chân ngôn Chuẩn Đề · Chú","tag":"Chú / Đà-la-ni","group":"chu","topics":["chu","hang-ngay"],"image":"assets/sutra-tu-bi.jpg","short":"Đà-la-ni gắn với Bồ Tát Chuẩn Đề và các nghi thức tu tập Bắc truyền.","intro":"Chú Chuẩn Đề xuất hiện trong các kinh điển và nghi quỹ liên quan đến Chuẩn Đề Phật Mẫu, trong đó có văn bản Đại Chánh tạng T1077. Bản phiên âm thông dụng có thể khác nhau theo đạo tràng.","source":"https://cbetaonline.dila.edu.tw/zh/T1077","sourceLabel":"Tham khảo kinh bản gốc","kind":"chu","sections":[["Giới thiệu về bài chú","Chú Chuẩn Đề xuất hiện trong các kinh điển và nghi quỹ liên quan đến Chuẩn Đề Phật Mẫu, trong đó có văn bản Đại Chánh tạng T1077. Bản phiên âm thông dụng có thể khác nhau theo đạo tràng."],["Nội dung và ý nghĩa","Thực tập với lòng thanh tịnh, giới hạnh và tâm nguyện hướng thiện."],["Gợi ý đọc và thực hành","Tìm bản phiên âm được cơ sở tu học sử dụng, không tự ghép các câu thần chú từ nhiều phiên bản."]]},{"id":"chu-vang-sanh","name":"Chú Vãng Sinh","pali":"Chân ngôn trong nghi thức Tịnh độ · Chú","tag":"Chú / Đà-la-ni","group":"chu","topics":["chu","hang-ngay","hoi-huong"],"image":"assets/sutra-hanh-phuc.jpg","short":"Đà-la-ni thường được trì tụng trong thời khóa Tịnh độ.","intro":"Chú Vãng Sinh là tên gọi phổ biến của một đà-la-ni trong nghi thức liên quan đến pháp môn Tịnh độ. Mã T0368 là văn bản gắn với nguyện sinh Tịnh độ; cách phiên âm tiếng Việt có nhiều lối truyền.","source":"https://www.thuvienhoasen.org/","sourceLabel":"Tra cứu nguồn tham khảo","kind":"chu","sections":[["Giới thiệu về bài chú","Chú Vãng Sinh là tên gọi phổ biến của một đà-la-ni trong nghi thức liên quan đến pháp môn Tịnh độ. Mã T0368 là văn bản gắn với nguyện sinh Tịnh độ; cách phiên âm tiếng Việt có nhiều lối truyền."],["Nội dung và ý nghĩa","Hướng tâm cầu sinh về cõi Tịnh độ và nuôi dưỡng tín, nguyện, hạnh theo truyền thống hành trì."],["Gợi ý đọc và thực hành","Nếu đang theo khóa lễ cụ thể, dùng đúng bản chú và thứ tự nghi thức của khóa lễ."]]},{"id":"chu-duoc-su","name":"Chú Dược Sư","pali":"Thần chú Dược Sư · liên hệ Kinh Dược Sư (T0450)","tag":"Chú / Đà-la-ni","group":"chu","topics":["chu","hang-ngay"],"image":"assets/sutra-phap-cu.jpg","short":"Đà-la-ni liên hệ tín ngưỡng và hạnh nguyện của Đức Phật Dược Sư.","intro":"Chú Dược Sư được trì tụng trong các nghi thức hướng đến việc nuôi dưỡng tâm thiện, chăm sóc sức khỏe và hạnh nguyện cứu khổ. Có nhiều bản phiên âm dựa trên các truyền thống văn bản.","source":"https://cbetaonline.dila.edu.tw/zh/T0450","sourceLabel":"Tham khảo kinh bản gốc","kind":"chu","sections":[["Giới thiệu về bài chú","Chú Dược Sư được trì tụng trong các nghi thức hướng đến việc nuôi dưỡng tâm thiện, chăm sóc sức khỏe và hạnh nguyện cứu khổ. Có nhiều bản phiên âm dựa trên các truyền thống văn bản."],["Nội dung và ý nghĩa","Nhắc đến trách nhiệm chăm sóc thân tâm, tu tập từ bi và giúp đỡ người bệnh; không thay thế chữa trị y khoa."],["Gợi ý đọc và thực hành","Học âm tụng từ nghi thức được xác nhận, kết hợp hành động thiết thực chăm sóc người bệnh."]]},{"id":"tam-kinh","name":"Bát Nhã Tâm Kinh","pali":"T0251 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua","hang-ngay","truoc-ngu"],"image":"assets/sutra-tu-bi.jpg","short":"Bản kinh ngắn nổi bật về trí tuệ Bát Nhã và tính Không.","intro":"Bát Nhã Tâm Kinh là một trong những kinh ngắn được tụng phổ biến nhất trong Phật giáo Đại thừa. Bản Hán dịch của ngài Huyền Trang được lưu trong Đại Chánh tạng dưới mã T0251.","source":"https://cbetaonline.dila.edu.tw/zh/T0251","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Bát Nhã Tâm Kinh là một trong những kinh ngắn được tụng phổ biến nhất trong Phật giáo Đại thừa. Bản Hán dịch của ngài Huyền Trang được lưu trong Đại Chánh tạng dưới mã T0251."],["Nội dung và ý nghĩa","Kinh nêu tinh thần quán chiếu năm uẩn và tính Không, nhằm giảm sự chấp thủ vào các hiện tượng và khái niệm."],["Gợi ý đọc và thực hành","Đọc chậm, tra cứu nghĩa các thuật ngữ “sắc”, “thọ”, “tưởng”, “hành”, “thức” và đối chiếu bản dịch đáng tin cậy."]]},{"id":"kim-cang","name":"Kinh Kim Cang","pali":"T0235 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua","hang-ngay"],"image":"assets/sutra-niem-xu.jpg","short":"Học tinh thần bố thí không chấp tướng và trí tuệ phá chấp.","intro":"Kinh Kim Cang thuộc hệ thống Bát Nhã Ba La Mật, là văn bản quan trọng trong Phật giáo Đại thừa. Bản Hán dịch nổi tiếng mang mã T0235.","source":"https://cbetaonline.dila.edu.tw/zh/T0235","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Kim Cang thuộc hệ thống Bát Nhã Ba La Mật, là văn bản quan trọng trong Phật giáo Đại thừa. Bản Hán dịch nổi tiếng mang mã T0235."],["Nội dung và ý nghĩa","Nhấn mạnh việc thực hành mà không chấp thủ vào cái tôi, người khác hay kết quả của hành động."],["Gợi ý đọc và thực hành","Khi làm một việc tốt, tập chú ý đến lợi ích của việc làm mà không quá mong được khen ngợi."]]},{"id":"phap-hoa","name":"Kinh Diệu Pháp Liên Hoa (Kinh Pháp Hoa)","pali":"T0262 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Kinh Đại thừa về phương tiện thiện xảo và con đường giác ngộ.","intro":"Kinh Pháp Hoa là bộ kinh lớn trong Phật giáo Đại thừa, nhấn mạnh phương tiện thiện xảo và khả năng giác ngộ của các chúng sinh. Bản Cưu Ma La Thập dịch mang mã T0262.","source":"https://cbetaonline.dila.edu.tw/zh/T0262","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Pháp Hoa là bộ kinh lớn trong Phật giáo Đại thừa, nhấn mạnh phương tiện thiện xảo và khả năng giác ngộ của các chúng sinh. Bản Cưu Ma La Thập dịch mang mã T0262."],["Nội dung và ý nghĩa","Những câu chuyện, thí dụ và phẩm kinh gợi mở cách giáo pháp được trình bày phù hợp căn cơ người học."],["Gợi ý đọc và thực hành","Bắt đầu từ các phẩm dễ tiếp cận như Phẩm Phương Tiện hoặc Phẩm Phổ Môn, đối chiếu bản dịch đầy đủ."]]},{"id":"pho-mon","name":"Kinh Phổ Môn – Phẩm Quán Thế Âm","pali":"T0262 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua","hang-ngay","truoc-ngu"],"image":"assets/sutra-phap-cu.jpg","short":"Phẩm thứ 25 của Kinh Pháp Hoa về hạnh nguyện cứu khổ của Bồ Tát Quán Thế Âm.","intro":"Phẩm Phổ Môn không phải bộ kinh tách biệt ở xuất xứ: đây là phẩm thứ 25 trong Kinh Diệu Pháp Liên Hoa (T0262), được nhiều chùa tụng riêng.","source":"https://cbetaonline.dila.edu.tw/zh/T0262","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Phẩm Phổ Môn không phải bộ kinh tách biệt ở xuất xứ: đây là phẩm thứ 25 trong Kinh Diệu Pháp Liên Hoa (T0262), được nhiều chùa tụng riêng."],["Nội dung và ý nghĩa","Gợi mở tinh thần lắng nghe tiếng kêu khổ và đem lòng từ bi vào hành động."],["Gợi ý đọc và thực hành","Đọc phẩm kinh và thử thực tập lắng nghe người thân bằng sự có mặt chân thành."]]},{"id":"a-di-da","name":"Kinh A Di Đà","pali":"T0366 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua","hang-ngay","truoc-ngu"],"image":"assets/sutra-tu-bi.jpg","short":"Kinh Tịnh độ giới thiệu Đức Phật A Di Đà và cõi Cực Lạc.","intro":"Kinh A Di Đà, thường gọi Tiểu Bản A Di Đà, thuộc nhóm kinh quan trọng của pháp môn Tịnh độ. Bản Hán dịch Cưu Ma La Thập mang mã T0366.","source":"https://cbetaonline.dila.edu.tw/zh/T0366","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh A Di Đà, thường gọi Tiểu Bản A Di Đà, thuộc nhóm kinh quan trọng của pháp môn Tịnh độ. Bản Hán dịch Cưu Ma La Thập mang mã T0366."],["Nội dung và ý nghĩa","Kinh khơi dậy tín tâm, nguyện lực và thực hành niệm Phật theo truyền thống Tịnh độ."],["Gợi ý đọc và thực hành","Tìm hiểu phần nghĩa kinh trước khi tụng; nếu niệm Phật, kết hợp sống hiền thiện và chăm sóc người xung quanh."]]},{"id":"vo-luong-tho","name":"Kinh Vô Lượng Thọ","pali":"T0360 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Giới thiệu những đại nguyện của Đức Phật A Di Đà trong truyền thống Tịnh độ.","intro":"Kinh Vô Lượng Thọ là một trong ba kinh thường được gọi là Tịnh độ tam kinh, trình bày hạnh nguyện của Đức Phật A Di Đà và con đường tu học liên quan.","source":"https://cbetaonline.dila.edu.tw/zh/T0360","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Vô Lượng Thọ là một trong ba kinh thường được gọi là Tịnh độ tam kinh, trình bày hạnh nguyện của Đức Phật A Di Đà và con đường tu học liên quan."],["Nội dung và ý nghĩa","Tín, nguyện và hạnh đi cùng việc vun bồi thiện nghiệp, tâm thanh tịnh và lòng từ bi."],["Gợi ý đọc và thực hành","Đọc theo từng phẩm nhỏ, ghi lại một hạnh nguyện muốn áp dụng trong đời sống."]]},{"id":"quan-vo-luong-tho","name":"Kinh Quán Vô Lượng Thọ","pali":"T0365 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-phap-cu.jpg","short":"Pháp môn quán tưởng, niệm Phật và hướng về Tịnh độ.","intro":"Kinh Quán Vô Lượng Thọ thuộc nhóm kinh chủ chốt của truyền thống Tịnh độ, thường được học cùng Kinh A Di Đà và Kinh Vô Lượng Thọ.","source":"https://cbetaonline.dila.edu.tw/zh/T0365","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Quán Vô Lượng Thọ thuộc nhóm kinh chủ chốt của truyền thống Tịnh độ, thường được học cùng Kinh A Di Đà và Kinh Vô Lượng Thọ."],["Nội dung và ý nghĩa","Trình bày các phép quán và phương hướng tu tập với tâm niệm Phật."],["Gợi ý đọc và thực hành","Nên đọc cùng lời giảng đáng tin cậy, tránh giản lược các phép quán sâu thành bài tập tưởng tượng tùy tiện."]]},{"id":"dia-tang","name":"Kinh Địa Tạng Bồ Tát Bổn Nguyện","pali":"T0412 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua","hoi-huong"],"image":"assets/sutra-hanh-phuc.jpg","short":"Kinh về hiếu đạo, cứu khổ và đại nguyện của Bồ Tát Địa Tạng.","intro":"Kinh Địa Tạng Bồ Tát Bổn Nguyện phổ biến trong Phật giáo Bắc truyền, với các chủ đề hiếu kính, nhân quả và lòng nguyện cứu giúp chúng sinh. Bản Hán văn có mã T0412.","source":"https://cbetaonline.dila.edu.tw/zh/T0412","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Địa Tạng Bồ Tát Bổn Nguyện phổ biến trong Phật giáo Bắc truyền, với các chủ đề hiếu kính, nhân quả và lòng nguyện cứu giúp chúng sinh. Bản Hán văn có mã T0412."],["Nội dung và ý nghĩa","Khuyến khích tinh thần báo ân, làm việc thiện và chuyển hóa hành vi."],["Gợi ý đọc và thực hành","Đọc theo phẩm, quán chiếu cách thể hiện lòng hiếu kính bằng việc chăm sóc người thân còn hiện tiền."]]},{"id":"duoc-su","name":"Kinh Dược Sư","pali":"T0450 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua","hang-ngay"],"image":"assets/sutra-phap-cu.jpg","short":"Kinh về mười hai đại nguyện của Đức Phật Dược Sư Lưu Ly Quang.","intro":"Kinh Dược Sư trình bày hạnh nguyện của Đức Phật Dược Sư, được tụng rộng rãi trong truyền thống Bắc truyền để phát tâm hướng thiện và cứu khổ.","source":"https://cbetaonline.dila.edu.tw/zh/T0450","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Dược Sư trình bày hạnh nguyện của Đức Phật Dược Sư, được tụng rộng rãi trong truyền thống Bắc truyền để phát tâm hướng thiện và cứu khổ."],["Nội dung và ý nghĩa","Nhấn mạnh lòng từ bi, các hành động thiện lành và sự nâng đỡ người đang bệnh khổ."],["Gợi ý đọc và thực hành","Đọc một đại nguyện và liên hệ với hành động chăm sóc sức khỏe, giúp đỡ người bệnh trong khả năng."]]},{"id":"hoa-nghiem","name":"Kinh Đại Phương Quảng Phật Hoa Nghiêm","pali":"T0279 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Bộ kinh lớn về hạnh Bồ Tát và tương quan trùng trùng duyên khởi.","intro":"Kinh Hoa Nghiêm là đại bộ kinh quan trọng của Phật giáo Đại thừa. Bản dịch Hán 80 quyển được lưu dưới mã T0279 trong Đại Chánh tạng.","source":"https://cbetaonline.dila.edu.tw/zh/T0279","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Hoa Nghiêm là đại bộ kinh quan trọng của Phật giáo Đại thừa. Bản dịch Hán 80 quyển được lưu dưới mã T0279 trong Đại Chánh tạng."],["Nội dung và ý nghĩa","Nhấn mạnh hạnh nguyện Bồ Tát, sự liên hệ sâu rộng giữa các hiện tượng và con đường thực hành trí tuệ, từ bi."],["Gợi ý đọc và thực hành","Có thể bắt đầu với Phẩm Phổ Hiền Hạnh Nguyện, rồi đọc tiếp từng phần cùng chú giải."]]},{"id":"pho-hien-hanh-nguyen","name":"Phẩm Phổ Hiền Hạnh Nguyện","pali":"T0293 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua","hang-ngay","hoi-huong"],"image":"assets/sutra-tu-bi.jpg","short":"Học mười đại nguyện của Bồ Tát Phổ Hiền trong truyền thống Hoa Nghiêm.","intro":"Phẩm Phổ Hiền Hạnh Nguyện thường được tụng riêng, trình bày mười đại nguyện làm nền tảng cho việc thực hành Bồ Tát đạo. Trong hệ thống Đại Chánh tạng có bản T0293.","source":"https://cbetaonline.dila.edu.tw/zh/T0293","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Phẩm Phổ Hiền Hạnh Nguyện thường được tụng riêng, trình bày mười đại nguyện làm nền tảng cho việc thực hành Bồ Tát đạo. Trong hệ thống Đại Chánh tạng có bản T0293."],["Nội dung và ý nghĩa","Những đại nguyện nhắc đến lễ kính, tán thán, cúng dường, sám hối, tùy hỷ và hồi hướng."],["Gợi ý đọc và thực hành","Chọn một đại nguyện ứng dụng trong ngày, như tùy hỷ khi thấy người khác làm điều tốt."]]},{"id":"lang-nghiem","name":"Kinh Thủ Lăng Nghiêm","pali":"T0945 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-phap-cu.jpg","short":"Kinh Bắc truyền bàn sâu về tâm, căn trần và con đường tu định.","intro":"Kinh Thủ Lăng Nghiêm là văn bản được lưu hành rộng trong Phật giáo Hán truyền. Đây là một kinh dài, có nhiều tầng giáo nghĩa và nghi thức tu tập liên quan.","source":"https://cbetaonline.dila.edu.tw/zh/T0945","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Thủ Lăng Nghiêm là văn bản được lưu hành rộng trong Phật giáo Hán truyền. Đây là một kinh dài, có nhiều tầng giáo nghĩa và nghi thức tu tập liên quan."],["Nội dung và ý nghĩa","Gợi ý quán chiếu về tâm nhận biết, việc buông chấp trước và tầm quan trọng của giới hạnh khi tu tập."],["Gợi ý đọc và thực hành","Đọc cùng lời giảng của vị thầy có chuyên môn, không dựa vào một đoạn trích rời rạc để kết luận toàn bộ kinh."]]},{"id":"duy-ma-cat","name":"Kinh Duy Ma Cật","pali":"T0475 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-niem-xu.jpg","short":"Cuộc đối thoại sâu sắc về bất nhị, trí tuệ và đời sống cư sĩ.","intro":"Kinh Duy Ma Cật là tác phẩm Đại thừa nổi tiếng với nhân vật cư sĩ Duy Ma Cật, thể hiện khả năng tu học giữa đời sống thế tục. Bản Hán dịch mang mã T0475.","source":"https://cbetaonline.dila.edu.tw/zh/T0475","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Duy Ma Cật là tác phẩm Đại thừa nổi tiếng với nhân vật cư sĩ Duy Ma Cật, thể hiện khả năng tu học giữa đời sống thế tục. Bản Hán dịch mang mã T0475."],["Nội dung và ý nghĩa","Tinh thần bất nhị và trí tuệ đi cùng lòng bi mẫn, phá bỏ những định kiến máy móc về thực hành."],["Gợi ý đọc và thực hành","Chú ý cách các nhân vật đặt câu hỏi và đối thoại, rồi liên hệ với thái độ học hỏi khi bất đồng quan điểm."]]},{"id":"vien-giac","name":"Kinh Viên Giác","pali":"T0842 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-tu-bi.jpg","short":"Đối thoại về giác ngộ và các phương pháp thực hành trong Bắc truyền.","intro":"Kinh Viên Giác là một văn bản được nghiên cứu trong truyền thống Đại thừa Đông Á, trình bày các cuộc hỏi đáp giữa chư Bồ Tát và Đức Phật.","source":"https://cbetaonline.dila.edu.tw/zh/T0842","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Viên Giác là một văn bản được nghiên cứu trong truyền thống Đại thừa Đông Á, trình bày các cuộc hỏi đáp giữa chư Bồ Tát và Đức Phật."],["Nội dung và ý nghĩa","Gợi mở cách nhận diện vọng tưởng, nuôi dưỡng tuệ giác và thực hành phù hợp căn cơ."],["Gợi ý đọc và thực hành","Đọc chậm từng chương kèm chú giải, tránh hiểu các khái niệm như “giác” hay “không” theo nghĩa hư vô."]]},{"id":"lang-gia","name":"Kinh Lăng Già","pali":"T0670 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-niem-xu.jpg","short":"Kinh về tâm thức, nhận thức và con đường chuyển hóa chấp trước.","intro":"Kinh Lăng Già là kinh điển có ảnh hưởng lớn trong lịch sử tư tưởng Đại thừa, nhất là các thảo luận về duy tâm, tâm thức và trí tuệ.","source":"https://cbetaonline.dila.edu.tw/zh/T0670","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Lăng Già là kinh điển có ảnh hưởng lớn trong lịch sử tư tưởng Đại thừa, nhất là các thảo luận về duy tâm, tâm thức và trí tuệ."],["Nội dung và ý nghĩa","Khuyến khích khảo sát cách nhận thức hình thành và vì sao sự chấp thủ vào khái niệm có thể gây khổ."],["Gợi ý đọc và thực hành","Văn bản khó; nên đọc có hướng dẫn và phân biệt thuật ngữ triết học với cách dùng hằng ngày."]]},{"id":"bat-dai-nhan-giac","name":"Kinh Bát Đại Nhân Giác","pali":"T0779 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua","hang-ngay"],"image":"assets/sutra-hoi-tho.jpg","short":"Tám điều giác ngộ gợi ý nếp sống giản dị, tỉnh thức và biết đủ.","intro":"Kinh Bát Đại Nhân Giác là một kinh ngắn được tụng và học trong Phật giáo Bắc truyền. Văn bản Hán có mã T0779.","source":"https://cbetaonline.dila.edu.tw/zh/T0779","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Bát Đại Nhân Giác là một kinh ngắn được tụng và học trong Phật giáo Bắc truyền. Văn bản Hán có mã T0779."],["Nội dung và ý nghĩa","Nhắc việc thấy tính vô thường, bớt tham dục, tinh tấn và nuôi dưỡng tâm rộng lớn."],["Gợi ý đọc và thực hành","Chọn một điều giác ngộ, viết một hành động thiết thực phù hợp với điều ấy trong hôm nay."]]},{"id":"tu-thap-nhi-chuong","name":"Kinh Tứ Thập Nhị Chương","pali":"T0784 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Bốn mươi hai chương dạy về giới hạnh và tu tập, quen thuộc trong Hán truyền.","intro":"Kinh Tứ Thập Nhị Chương là một văn bản Phật giáo Hán truyền gồm nhiều đoạn giáo huấn ngắn, thường được dùng làm tài liệu nhập môn.","source":"https://cbetaonline.dila.edu.tw/zh/T0784","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Tứ Thập Nhị Chương là một văn bản Phật giáo Hán truyền gồm nhiều đoạn giáo huấn ngắn, thường được dùng làm tài liệu nhập môn."],["Nội dung và ý nghĩa","Khuyến khích tiết chế dục vọng, giữ giới, tinh tấn và sống chân thật."],["Gợi ý đọc và thực hành","Chọn một chương ngắn để đọc, suy ngẫm và đối chiếu bản dịch kỹ lưỡng."]]},{"id":"di-giao","name":"Kinh Di Giáo","pali":"T0389 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-hanh-phuc.jpg","short":"Lời giáo huấn về giới, định, tuệ và tinh tấn được truyền thống ghi nhớ.","intro":"Kinh Di Giáo, còn được gọi Kinh Lời Dạy Cuối Cùng, là tác phẩm ngắn được lưu truyền trong Phật giáo Hán truyền.","source":"https://cbetaonline.dila.edu.tw/zh/T0389","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Di Giáo, còn được gọi Kinh Lời Dạy Cuối Cùng, là tác phẩm ngắn được lưu truyền trong Phật giáo Hán truyền."],["Nội dung và ý nghĩa","Nhấn mạnh tính thiết yếu của giới hạnh, sự tiết chế và tinh tấn trên đường tu học."],["Gợi ý đọc và thực hành","Đọc một đoạn mỗi ngày và chọn một thói quen nên điều chỉnh."]]},{"id":"thang-man","name":"Kinh Thắng Man","pali":"T0353 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-tu-bi.jpg","short":"Lời phát nguyện và giáo nghĩa sâu sắc của phu nhân Thắng Man.","intro":"Kinh Thắng Man kể về lời phát nguyện và thảo luận giáo pháp của phu nhân Thắng Man, được xem là tác phẩm quan trọng trong tư tưởng Đại thừa.","source":"https://cbetaonline.dila.edu.tw/zh/T0353","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Thắng Man kể về lời phát nguyện và thảo luận giáo pháp của phu nhân Thắng Man, được xem là tác phẩm quan trọng trong tư tưởng Đại thừa."],["Nội dung và ý nghĩa","Đề cao niềm tin, giới hạnh, trách nhiệm và khả năng thực hành Bồ Tát đạo."],["Gợi ý đọc và thực hành","Đọc từng đoạn gắn với chủ đề giữ lời hứa, hành động có trách nhiệm và giúp đời."]]},{"id":"dai-bat-niet-ban","name":"Kinh Đại Bát Niết Bàn (Đại thừa)","pali":"T0374 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-phap-cu.jpg","short":"Bộ kinh Đại thừa về Phật tính, giải thoát và trí tuệ.","intro":"Kinh Đại Bát Niết Bàn của truyền thống Đại thừa là văn bản khác với Kinh Đại Bát Niết Bàn DN 16 trong Trường Bộ Pāli. Cần phân biệt rõ hai tác phẩm khi tìm hiểu.","source":"https://cbetaonline.dila.edu.tw/zh/T0374","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Đại Bát Niết Bàn của truyền thống Đại thừa là văn bản khác với Kinh Đại Bát Niết Bàn DN 16 trong Trường Bộ Pāli. Cần phân biệt rõ hai tác phẩm khi tìm hiểu."],["Nội dung và ý nghĩa","Bàn về Phật tính, giác ngộ và những khái niệm giáo lý phong phú trong Đại thừa."],["Gợi ý đọc và thực hành","Đối chiếu bản dịch và chú giải khi đọc các đoạn về “thường”, “lạc”, “ngã”, “tịnh”."]]},{"id":"bao-tich","name":"Kinh Đại Bảo Tích","pali":"T0310 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Tập hợp nhiều hội kinh trình bày các pháp môn Bồ Tát.","intro":"Kinh Đại Bảo Tích là một đại tập kinh gồm nhiều hội có nội dung, nhân vật và phương pháp tu khác nhau.","source":"https://cbetaonline.dila.edu.tw/zh/T0310","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Đại Bảo Tích là một đại tập kinh gồm nhiều hội có nội dung, nhân vật và phương pháp tu khác nhau."],["Nội dung và ý nghĩa","Là kho tư liệu lớn về bố thí, giới hạnh, Bồ Tát đạo và trí tuệ trong truyền thống Đại thừa."],["Gợi ý đọc và thực hành","Nên chọn một hội kinh cụ thể thay vì đọc toàn bộ theo kiểu lướt nhanh."]]},{"id":"phap-bao-dan","name":"Pháp Bảo Đàn Kinh","pali":"T2008 · Kinh văn","tag":"Kinh văn","group":"dai-thua","topics":["dai-thua"],"image":"assets/sutra-hoi-tho.jpg","short":"Văn bản Thiền tông gắn với Lục Tổ Huệ Năng, không phải kinh do Đức Phật trực tiếp thuyết.","intro":"Pháp Bảo Đàn Kinh có chữ “kinh” trong tên truyền thống, nhưng thuộc ngữ lục/thiền văn gắn với Lục Tổ Huệ Năng; cần phân biệt với kinh Phật thuộc Nikāya hoặc kinh Đại thừa.","source":"https://cbetaonline.dila.edu.tw/zh/T2008","sourceLabel":"CBETA – Hán văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Pháp Bảo Đàn Kinh có chữ “kinh” trong tên truyền thống, nhưng thuộc ngữ lục/thiền văn gắn với Lục Tổ Huệ Năng; cần phân biệt với kinh Phật thuộc Nikāya hoặc kinh Đại thừa."],["Nội dung và ý nghĩa","Nhấn mạnh trực nhận, trí tuệ và thực hành giữa đời thường trong truyền thống Thiền tông Đông Á."],["Gợi ý đọc và thực hành","Đọc cùng bối cảnh lịch sử và chú giải, tránh tách câu “vô niệm” khỏi toàn văn."]]},{"id":"kala-ma","name":"Kinh Kālāma","pali":"AN 3.65 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","nen-tang"],"image":"assets/sutra-niem-xu.jpg","short":"Khuyến khích khảo sát cẩn trọng thay vì chỉ tin theo lời đồn hoặc uy tín.","intro":"Kinh Kālāma (AN 3.65), còn gọi Kinh Kesamutti, trình bày cuộc đối thoại về cách nhận biết điều nên tin và nên thực hành.","source":"https://suttacentral.net/an3.65","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Kālāma (AN 3.65), còn gọi Kinh Kesamutti, trình bày cuộc đối thoại về cách nhận biết điều nên tin và nên thực hành."],["Nội dung và ý nghĩa","Khảo sát hậu quả thiện và bất thiện của hành động, cùng vai trò của tham, sân, si trong nhận thức."],["Gợi ý đọc và thực hành","Trước một thông tin gây kích động, thử kiểm tra nguồn, tác động và động cơ của chính mình."]]},{"id":"giao-tho-thi-ca-la-viet","name":"Kinh Giáo thọ Thi-ca-la-việt","pali":"DN 31 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","hang-ngay"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Đạo đức và trách nhiệm trong gia đình, bạn bè, công việc và xã hội.","intro":"Kinh DN 31, thường biết đến với tên Sigālovāda, là một bài kinh nổi bật dành cho đời sống cư sĩ, sử dụng hình ảnh sáu phương để nói về các mối quan hệ.","source":"https://suttacentral.net/dn31","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh DN 31, thường biết đến với tên Sigālovāda, là một bài kinh nổi bật dành cho đời sống cư sĩ, sử dụng hình ảnh sáu phương để nói về các mối quan hệ."],["Nội dung và ý nghĩa","Đề cao bổn phận qua lại, sự trung thực, biết ơn và ứng xử có trách nhiệm."],["Gợi ý đọc và thực hành","Chọn một mối quan hệ để thực hành quan tâm, giữ lời hứa và tôn trọng."]]},{"id":"dai-bat-niet-ban-pali","name":"Kinh Đại Bát Niết Bàn (Trường Bộ)","pali":"DN 16 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-phap-cu.jpg","short":"Những sự kiện và lời dạy được ghi lại trong giai đoạn cuối đời Đức Phật.","intro":"Kinh Đại Bát Niết Bàn DN 16 là một bài kinh dài trong Trường Bộ, thuật lại hành trình cuối đời của Đức Phật và nhiều lời dạy liên quan đến cộng đồng tu học.","source":"https://suttacentral.net/dn16","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Đại Bát Niết Bàn DN 16 là một bài kinh dài trong Trường Bộ, thuật lại hành trình cuối đời của Đức Phật và nhiều lời dạy liên quan đến cộng đồng tu học."],["Nội dung và ý nghĩa","Nhấn mạnh tính vô thường, tinh thần tự nương tựa vào chánh pháp và sự tinh tấn."],["Gợi ý đọc và thực hành","Đọc theo từng đoạn; ghi lại một câu hỏi về vô thường và trách nhiệm tu học."]]},{"id":"dai-niem-xu","name":"Kinh Đại Niệm Xứ","pali":"DN 22 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","chanh-niem"],"image":"assets/sutra-hoi-tho.jpg","short":"Một bản trình bày rộng về bốn nền tảng chánh niệm.","intro":"Kinh Đại Niệm Xứ DN 22 thuộc Trường Bộ, liên hệ mật thiết với Kinh Niệm Xứ MN 10 nhưng có cấu trúc mở rộng ở một số phần.","source":"https://suttacentral.net/dn22","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Đại Niệm Xứ DN 22 thuộc Trường Bộ, liên hệ mật thiết với Kinh Niệm Xứ MN 10 nhưng có cấu trúc mở rộng ở một số phần."],["Nội dung và ý nghĩa","Trình bày sự quán sát thân, thọ, tâm và pháp nhằm phát triển hiểu biết trực tiếp."],["Gợi ý đọc và thực hành","Đọc từng lĩnh vực quán niệm, bắt đầu với hơi thở hoặc cảm giác nơi thân."]]},{"id":"sa-mon-qua","name":"Kinh Sa-môn Quả","pali":"DN 2 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Những kết quả của đời sống tu hành được thảo luận qua cuộc đối thoại với vua A-xà-thế.","intro":"Kinh Sa-môn Quả DN 2 trình bày một câu hỏi về lợi ích thực tế của đời sống xuất gia và lời giải đáp theo từng bước tu tập.","source":"https://suttacentral.net/dn2","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Sa-môn Quả DN 2 trình bày một câu hỏi về lợi ích thực tế của đời sống xuất gia và lời giải đáp theo từng bước tu tập."],["Nội dung và ý nghĩa","Cho thấy mối liên hệ giữa đạo đức, sự phòng hộ các căn, thiền định và trí tuệ."],["Gợi ý đọc và thực hành","Nhận diện một lợi ích nhỏ của việc giữ lời nói chân thật và sống có kỷ luật."]]},{"id":"vo-nga-tuong","name":"Kinh Vô Ngã Tướng","pali":"SN 22.59 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","nen-tang"],"image":"assets/sutra-niem-xu.jpg","short":"Quán chiếu năm uẩn dưới ánh sáng vô thường và vô ngã.","intro":"Kinh Vô Ngã Tướng SN 22.59 là bài kinh quan trọng trong Tương Ưng Bộ về năm uẩn và sự không nên chấp chúng là tự ngã bất biến.","source":"https://suttacentral.net/sn22.59","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Vô Ngã Tướng SN 22.59 là bài kinh quan trọng trong Tương Ưng Bộ về năm uẩn và sự không nên chấp chúng là tự ngã bất biến."],["Nội dung và ý nghĩa","Giúp người học giảm đồng nhất bản thân với những hiện tượng luôn thay đổi."],["Gợi ý đọc và thực hành","Quan sát một cảm xúc đến rồi đi, ghi nhận mà không tự gọi mình bằng tên cảm xúc ấy."]]},{"id":"kinh-lua-chay","name":"Kinh Lửa Cháy","pali":"SN 35.28 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-hanh-phuc.jpg","short":"Dụ ngôn ngọn lửa để nhận diện tham, sân, si trong trải nghiệm giác quan.","intro":"Kinh SN 35.28 còn được gọi Adittapariyāya Sutta, trình bày cách các căn và đối tượng có thể bị thiêu đốt bởi tham, sân, si.","source":"https://suttacentral.net/sn35.28","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh SN 35.28 còn được gọi Adittapariyāya Sutta, trình bày cách các căn và đối tượng có thể bị thiêu đốt bởi tham, sân, si."],["Nội dung và ý nghĩa","Nhắc người tu học quan sát phản ứng trước những gì thấy, nghe, cảm nhận."],["Gợi ý đọc và thực hành","Khi gặp nội dung làm bực bội trên mạng, nhận ra phản ứng trước khi bấm chia sẻ."]]},{"id":"nhan-duyen","name":"Kinh Phân Biệt Duyên Khởi","pali":"SN 12.2 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","nen-tang"],"image":"assets/sutra-niem-xu.jpg","short":"Giới thiệu các chi phần duyên khởi trong giáo lý Phật giáo.","intro":"Kinh SN 12.2 trình bày cách phân biệt các mắt xích duyên khởi, một nội dung trọng yếu trong giáo lý về sự sinh khởi và chấm dứt khổ.","source":"https://suttacentral.net/sn12.2","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh SN 12.2 trình bày cách phân biệt các mắt xích duyên khởi, một nội dung trọng yếu trong giáo lý về sự sinh khởi và chấm dứt khổ."],["Nội dung và ý nghĩa","Gợi hiểu hiện tượng phụ thuộc điều kiện, không tự tồn tại độc lập hoặc bất biến."],["Gợi ý đọc và thực hành","Nhận diện những điều kiện đang nuôi một thói quen không tốt và thử thay đổi một điều kiện nhỏ."]]},{"id":"nam-dieu-quan-niem","name":"Kinh Năm Điều Quán Niệm","pali":"AN 5.57 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","hang-ngay","truoc-ngu"],"image":"assets/sutra-hanh-phuc.jpg","short":"Năm sự thật về già, bệnh, chết, chia lìa và nghiệp.","intro":"Kinh AN 5.57 (Upajjhatthāna Sutta) nhắc người tu học thường xuyên quán niệm những điều tất yếu của đời sống và trách nhiệm đối với hành động.","source":"https://suttacentral.net/an5.57","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh AN 5.57 (Upajjhatthāna Sutta) nhắc người tu học thường xuyên quán niệm những điều tất yếu của đời sống và trách nhiệm đối với hành động."],["Nội dung và ý nghĩa","Quán niệm vô thường để sống có ý nghĩa, không phải để làm mình sợ hãi."],["Gợi ý đọc và thực hành","Đọc chậm một điều quán niệm và chọn một hành động thể hiện sự trân quý thời gian."]]},{"id":"nhat-da-hien-gia","name":"Kinh Nhất Dạ Hiền Giả","pali":"MN 131 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","chanh-niem","truoc-ngu"],"image":"assets/sutra-hoi-tho.jpg","short":"Sống tỉnh thức trong hiện tại, không chạy theo quá khứ hay tương lai.","intro":"Kinh Nhất Dạ Hiền Giả MN 131 hướng dẫn cách không bị kéo đi bởi chuyện đã qua hay điều chưa tới, đồng thời không bỏ quên việc cần làm hôm nay.","source":"https://suttacentral.net/mn131","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Nhất Dạ Hiền Giả MN 131 hướng dẫn cách không bị kéo đi bởi chuyện đã qua hay điều chưa tới, đồng thời không bỏ quên việc cần làm hôm nay."],["Nội dung và ý nghĩa","Thực tập hiện diện trong hiện tại mà vẫn giữ sự sáng suốt và trách nhiệm."],["Gợi ý đọc và thực hành","Trước khi ngủ, ghi lại một việc đã hoàn tất, rồi cho phép mình nghỉ ngơi."]]},{"id":"giao-gioi-la-hau-la","name":"Kinh Giáo Giới La-hầu-la ở Rừng Am-ba-la","pali":"MN 61 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","hang-ngay"],"image":"assets/sutra-niem-xu.jpg","short":"Lời dạy về sự trung thực và tự xem xét hành động trước, trong và sau khi làm.","intro":"Kinh MN 61 là lời giáo huấn dành cho La-hầu-la, dùng nhiều ví dụ gần gũi để dạy việc nói thật và quán sát hậu quả của hành động.","source":"https://suttacentral.net/mn61","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 61 là lời giáo huấn dành cho La-hầu-la, dùng nhiều ví dụ gần gũi để dạy việc nói thật và quán sát hậu quả của hành động."],["Nội dung và ý nghĩa","Khuyến khích tự chịu trách nhiệm, biết sửa sai và không cố chấp bảo vệ lỗi lầm."],["Gợi ý đọc và thực hành","Trước một quyết định, hỏi: việc này có hại mình hay hại người không?"]]},{"id":"giao-gioi-la-hau-la-lon","name":"Đại Kinh Giáo Giới La-hầu-la","pali":"MN 62 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","chanh-niem"],"image":"assets/sutra-hoi-tho.jpg","short":"Bài học về các đại và phương pháp tu tập hơi thở, tâm từ.","intro":"Kinh MN 62 tiếp tục những lời hướng dẫn La-hầu-la, trình bày việc quán sát các yếu tố thân và những phương pháp tu tập.","source":"https://suttacentral.net/mn62","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 62 tiếp tục những lời hướng dẫn La-hầu-la, trình bày việc quán sát các yếu tố thân và những phương pháp tu tập."],["Nội dung và ý nghĩa","Hướng đến thái độ rộng lượng, không bị lay chuyển bởi cảm xúc nhất thời."],["Gợi ý đọc và thực hành","Thử nhận biết thân như đất, nước, lửa, gió trong một bài quán ngắn có hướng dẫn."]]},{"id":"vi-du-cai-cua","name":"Kinh Ví Dụ Cái Cưa","pali":"MN 21 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","tu-bi"],"image":"assets/sutra-phap-cu.jpg","short":"Một bài kinh sâu sắc về cách giữ tâm không sân hận khi bị xúc phạm.","intro":"Kinh MN 21 sử dụng những ví dụ mạnh mẽ để nói về rèn luyện lòng từ và không nuôi dưỡng ác ý ngay trong hoàn cảnh khó.","source":"https://suttacentral.net/mn21","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 21 sử dụng những ví dụ mạnh mẽ để nói về rèn luyện lòng từ và không nuôi dưỡng ác ý ngay trong hoàn cảnh khó."],["Nội dung và ý nghĩa","Không đồng nghĩa với việc chấp nhận bị bạo hành; mục tiêu là giữ chánh niệm và ứng xử không thù hận."],["Gợi ý đọc và thực hành","Tập nhận biết cảm xúc giận dữ, tìm cách giữ an toàn và nói rõ giới hạn bằng lời không xúc phạm."]]},{"id":"song-tam","name":"Kinh Song Tầm","pali":"MN 19 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","nen-tang"],"image":"assets/sutra-niem-xu.jpg","short":"Phân biệt các hướng suy nghĩ đưa đến tổn hại và các hướng suy nghĩ thiện lành.","intro":"Kinh MN 19 trình bày việc phân loại và quan sát các dòng tư duy trong quá trình rèn luyện tâm.","source":"https://suttacentral.net/mn19","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 19 trình bày việc phân loại và quan sát các dòng tư duy trong quá trình rèn luyện tâm."],["Nội dung và ý nghĩa","Ý nghĩ được nuôi dưỡng thường xuyên sẽ ảnh hưởng đến khuynh hướng của tâm và hành vi."],["Gợi ý đọc và thực hành","Khi thấy suy nghĩ tiêu cực lặp lại, thử chuyển sự chú ý đến một điều có ích và có thể thực hiện."]]},{"id":"an-tru-tam","name":"Kinh An Trú Tầm","pali":"MN 20 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","chanh-niem"],"image":"assets/sutra-hoi-tho.jpg","short":"Năm phương pháp điều phục các tư duy bất thiện.","intro":"Kinh MN 20 giới thiệu nhiều phương án xử lý khi ý nghĩ không lành chiếm ưu thế, trong đó có việc chuyển đối tượng chú ý.","source":"https://suttacentral.net/mn20","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 20 giới thiệu nhiều phương án xử lý khi ý nghĩ không lành chiếm ưu thế, trong đó có việc chuyển đối tượng chú ý."],["Nội dung và ý nghĩa","Đòi hỏi quan sát kỹ trạng thái tâm và áp dụng phương pháp phù hợp, không tự ép buộc máy móc."],["Gợi ý đọc và thực hành","Khi khó tập trung, thử chuyển sang một đối tượng thiện lành hoặc nghỉ một nhịp trước khi tiếp tục."]]},{"id":"tat-ca-lau-hoac","name":"Kinh Tất Cả Lậu Hoặc","pali":"MN 2 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Những phương pháp để ngăn ngừa và đoạn trừ các phiền não.","intro":"Kinh MN 2 bàn về những hình thức tu tập để đối trị lậu hoặc, từ cách nhìn nhận đến chế ngự và tránh duyên bất thiện.","source":"https://suttacentral.net/mn2","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 2 bàn về những hình thức tu tập để đối trị lậu hoặc, từ cách nhìn nhận đến chế ngự và tránh duyên bất thiện."],["Nội dung và ý nghĩa","Nêu tầm quan trọng của nhận thức đúng và sự thực hành phù hợp hoàn cảnh."],["Gợi ý đọc và thực hành","Thử xác định một thói quen gây hại cần tránh điều kiện kích hoạt và một hành động thay thế."]]},{"id":"vi-du-tam","name":"Kinh Ví Dụ Tấm Vải","pali":"MN 7 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","tu-bi"],"image":"assets/sutra-tu-bi.jpg","short":"Hình ảnh tấm vải bị nhuộm để nói về sự thanh lọc tâm.","intro":"Kinh MN 7 dùng hình ảnh tấm vải để thảo luận những cấu uế của tâm và khả năng chuyển hóa qua tu tập.","source":"https://suttacentral.net/mn7","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 7 dùng hình ảnh tấm vải để thảo luận những cấu uế của tâm và khả năng chuyển hóa qua tu tập."],["Nội dung và ý nghĩa","Giúp nhận diện các trạng thái bất thiện thay vì che giấu hoặc biện hộ cho chúng."],["Gợi ý đọc và thực hành","Chọn một biểu hiện ganh tị, kiêu mạn hoặc giận hờn và nhìn nó với sự thành thật."]]},{"id":"chinh-kien","name":"Kinh Chánh Tri Kiến","pali":"MN 9 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","nen-tang"],"image":"assets/sutra-niem-xu.jpg","short":"Giải thích các phương diện của chánh kiến qua nghiệp và duyên khởi.","intro":"Kinh MN 9 có hình thức đối thoại giáo pháp, bàn về chánh kiến và nhiều chủ đề nền tảng trong sự hiểu biết Phật học.","source":"https://suttacentral.net/mn9","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 9 có hình thức đối thoại giáo pháp, bàn về chánh kiến và nhiều chủ đề nền tảng trong sự hiểu biết Phật học."],["Nội dung và ý nghĩa","Nhắc rằng thấy biết đúng liên hệ với nhân quả, trách nhiệm đạo đức và con đường chấm dứt khổ."],["Gợi ý đọc và thực hành","Đọc cùng sơ đồ Tứ Diệu Đế để kết nối các khái niệm khi học."]]},{"id":"trung-dao","name":"Kinh Trung Đạo","pali":"SN 12.15 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","nen-tang"],"image":"assets/sutra-niem-xu.jpg","short":"Tránh cực đoan có và không trong cái nhìn về hiện tượng.","intro":"Kinh Kaccānagotta SN 12.15 là văn bản nổi tiếng về chánh kiến và sự tránh hai cực đoan khi hiểu về thế giới.","source":"https://suttacentral.net/sn12.15","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Kaccānagotta SN 12.15 là văn bản nổi tiếng về chánh kiến và sự tránh hai cực đoan khi hiểu về thế giới."],["Nội dung và ý nghĩa","Thay cho cái nhìn cố định, thấy sự sinh khởi và hoại diệt tùy nhân duyên."],["Gợi ý đọc và thực hành","Khi tranh luận, thử nhận ra những điều kiện khiến mỗi bên có góc nhìn khác nhau."]]},{"id":"phan-biet-su-that","name":"Kinh Phân Biệt Sự Thật","pali":"MN 141 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","nen-tang"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Trình bày rõ Tứ Diệu Đế qua lời giảng của Tôn giả Xá-lợi-phất.","intro":"Kinh MN 141 là bài kinh phân tích bốn sự thật cao quý và tám yếu tố của con đường tu tập.","source":"https://suttacentral.net/mn141","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 141 là bài kinh phân tích bốn sự thật cao quý và tám yếu tố của con đường tu tập."],["Nội dung và ý nghĩa","Giúp người mới học xây dựng hệ thống khái niệm đầy đủ hơn sau khi đọc Kinh Chuyển Pháp Luân."],["Gợi ý đọc và thực hành","Đọc và viết lại Bát Chánh Đạo theo cách hiểu của mình, đối chiếu với bản kinh."]]},{"id":"dai-kinh-bon-muoi","name":"Đại Kinh Bốn Mươi","pali":"MN 117 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","nen-tang"],"image":"assets/sutra-niem-xu.jpg","short":"Giải thích mối liên hệ giữa chánh kiến và các chi phần Bát Chánh Đạo.","intro":"Kinh MN 117 trình bày cấu trúc con đường tu học với nhiều phân biệt sâu về chánh kiến và các yếu tố đạo lộ.","source":"https://suttacentral.net/mn117","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 117 trình bày cấu trúc con đường tu học với nhiều phân biệt sâu về chánh kiến và các yếu tố đạo lộ."],["Nội dung và ý nghĩa","Thấy các phẩm chất trên đường tu không độc lập mà nâng đỡ lẫn nhau."],["Gợi ý đọc và thực hành","Đọc từng chi phần một và tìm ví dụ trong giao tiếp hoặc công việc."]]},{"id":"vi-du-con-ran","name":"Kinh Ví Dụ Con Rắn","pali":"MN 22 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-hoi-tho.jpg","short":"Nhắc về việc nắm bắt giáo pháp đúng cách và tránh chấp thủ vào quan điểm.","intro":"Kinh MN 22 sử dụng thí dụ con rắn và chiếc bè để giải thích nguy cơ hiểu sai hoặc bám chặt vào giáo pháp.","source":"https://suttacentral.net/mn22","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 22 sử dụng thí dụ con rắn và chiếc bè để giải thích nguy cơ hiểu sai hoặc bám chặt vào giáo pháp."],["Nội dung và ý nghĩa","Tư duy cần phục vụ giải thoát và thực hành, không trở thành công cụ hơn thua."],["Gợi ý đọc và thực hành","Khi học một lời dạy mới, tìm hiểu ngữ cảnh và hỏi người có chuyên môn trước khi áp dụng."]]},{"id":"vi-du-dau-chan-voi","name":"Đại Kinh Ví Dụ Dấu Chân Voi","pali":"MN 28 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","nen-tang"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Giới thiệu sự tương quan giữa các pháp môn nền tảng.","intro":"Kinh MN 28 phân tích các yếu tố thân và nhiều nội dung giáo pháp qua hình ảnh dấu chân voi, hỗ trợ cách nhìn hệ thống.","source":"https://suttacentral.net/mn28","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 28 phân tích các yếu tố thân và nhiều nội dung giáo pháp qua hình ảnh dấu chân voi, hỗ trợ cách nhìn hệ thống."],["Nội dung và ý nghĩa","Khuyến khích quán sát thân thể với thái độ hiểu biết thay vì chấp chặt."],["Gợi ý đọc và thực hành","Quan sát cảm giác nơi cơ thể trong lúc đi bộ chậm; không cần gán thêm ý nghĩa huyền bí."]]},{"id":"cong-nghiep","name":"Tiểu Kinh Phân Biệt Nghiệp","pali":"MN 135 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","hang-ngay"],"image":"assets/sutra-niem-xu.jpg","short":"Phân tích mối liên hệ giữa hành động và quả trong đời sống.","intro":"Kinh MN 135 là cuộc đối thoại về nghiệp và các khác biệt trong đời sống con người.","source":"https://suttacentral.net/mn135","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 135 là cuộc đối thoại về nghiệp và các khác biệt trong đời sống con người."],["Nội dung và ý nghĩa","Đặt trọng tâm vào trách nhiệm của hành động có chủ ý, tránh hiểu nghiệp như định mệnh cố định."],["Gợi ý đọc và thực hành","Chọn một hành động thiện nhỏ có thể làm đều đặn thay vì đổ lỗi cho số phận."]]},{"id":"lon-cong-nghiep","name":"Đại Kinh Phân Biệt Nghiệp","pali":"MN 136 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-phap-cu.jpg","short":"Một bài kinh tinh tế về tính phức tạp của quả nghiệp.","intro":"Kinh MN 136 giải thích vì sao không thể dựa vào một trường hợp riêng lẻ để kết luận đơn giản về nghiệp.","source":"https://suttacentral.net/mn136","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh MN 136 giải thích vì sao không thể dựa vào một trường hợp riêng lẻ để kết luận đơn giản về nghiệp."],["Nội dung và ý nghĩa","Giúp tránh thái độ phán xét người đang chịu khổ là “đáng phải chịu”."],["Gợi ý đọc và thực hành","Khi nghe chuyện bất hạnh, ưu tiên lòng cảm thông và trợ giúp thiết thực."]]},{"id":"kinh-chau-bau","name":"Kinh Châu Báu","pali":"Snp 2.1 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","hang-ngay"],"image":"assets/sutra-hanh-phuc.jpg","short":"Bài kinh tán thán Tam bảo, thường có trong truyền thống tụng niệm Pāli.","intro":"Kinh Châu Báu (Ratana Sutta, Snp 2.1) được tụng trong nhiều cộng đồng Phật giáo Nguyên thủy. Nội dung hướng về phẩm chất cao quý của Phật, Pháp và Tăng.","source":"https://suttacentral.net/snp2.1","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Châu Báu (Ratana Sutta, Snp 2.1) được tụng trong nhiều cộng đồng Phật giáo Nguyên thủy. Nội dung hướng về phẩm chất cao quý của Phật, Pháp và Tăng."],["Nội dung và ý nghĩa","Gợi lòng tin dựa trên phẩm hạnh và con đường tu tập, không chỉ ở hình thức nghi lễ."],["Gợi ý đọc và thực hành","Khi tụng, tìm hiểu ý nghĩa từng đoạn về Tam bảo thay vì chỉ đọc theo âm điệu."]]},{"id":"kinh-doc-cu","name":"Kinh Tê Ngưu Một Sừng","pali":"Snp 1.3 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","chanh-niem"],"image":"assets/sutra-hoi-tho.jpg","short":"Những bài kệ về đời sống độc cư và sự tự chủ trên đường tu.","intro":"Kinh Snp 1.3, thường được biết với hình ảnh tê ngưu một sừng, là bài kệ cổ nói về tinh thần độc lập trong tu tập.","source":"https://suttacentral.net/snp1.3","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh Snp 1.3, thường được biết với hình ảnh tê ngưu một sừng, là bài kệ cổ nói về tinh thần độc lập trong tu tập."],["Nội dung và ý nghĩa","Không nên hiểu một cách cực đoan là phải xa lánh hết mọi người; trọng tâm là không lệ thuộc vào sự bám víu."],["Gợi ý đọc và thực hành","Dành một khoảng lặng không điện thoại để quan sát thân và tâm."]]},{"id":"bang-cach-song","name":"Kinh Biết Sống Hiền Lành – Thiện nghiệp","pali":"AN 10.176 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","hang-ngay"],"image":"assets/sutra-tu-bi.jpg","short":"Mười đường nghiệp thiện và sự chăm sóc hành động thân, khẩu, ý.","intro":"Kinh AN 10.176 bàn về mười nghiệp đạo thiện và bất thiện trong đời sống.","source":"https://suttacentral.net/an10.176","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh AN 10.176 bàn về mười nghiệp đạo thiện và bất thiện trong đời sống."],["Nội dung và ý nghĩa","Chú ý thân hành, lời nói và ý nghĩ để hiểu nhân duyên đưa đến an lành."],["Gợi ý đọc và thực hành","Chọn một lời nói chân thật và đem lại lợi ích để thực tập trong hôm nay."]]},{"id":"ngu-triet","name":"Kinh Người Cư Sĩ","pali":"AN 5.179 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Những nguyên tắc và sự thực tập đạo đức trong đời sống tại gia.","intro":"Kinh AN 5.179 bàn đến đời sống và phẩm hạnh của người cư sĩ trong bối cảnh cộng đồng Phật giáo thời đầu.","source":"https://suttacentral.net/an5.179","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh AN 5.179 bàn đến đời sống và phẩm hạnh của người cư sĩ trong bối cảnh cộng đồng Phật giáo thời đầu."],["Nội dung và ý nghĩa","Nhắc rằng người tu tại gia cần phát triển đạo đức và quan hệ lành mạnh."],["Gợi ý đọc và thực hành","Đọc kinh, suy ngẫm về trách nhiệm của mình trong gia đình."]]},{"id":"quy-y","name":"Kinh Quy Y Tam Bảo – Giá trị của niềm tin","pali":"AN 8.39 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","hang-ngay"],"image":"assets/sutra-phap-cu.jpg","short":"Giới thiệu một cách tiếp cận về các nguồn công đức và đạo đức trong đời sống.","intro":"Kinh AN 8.39 là một bài kinh được trích dẫn trong các chủ đề thực hành công đức và giữ giới.","source":"https://suttacentral.net/an8.39","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh AN 8.39 là một bài kinh được trích dẫn trong các chủ đề thực hành công đức và giữ giới."],["Nội dung và ý nghĩa","Khuyến khích nuôi thiện nghiệp qua bố thí, giới hạnh và tâm từ."],["Gợi ý đọc và thực hành","Xem lại một việc làm lợi ích mà không gây hại người khác."]]},{"id":"bon-phap-vo-luong","name":"Bốn Tâm Vô Lượng","pali":"AN 4.125 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","tu-bi"],"image":"assets/sutra-tu-bi.jpg","short":"Tìm hiểu tâm từ, tâm bi, tâm hỷ và tâm xả trong giáo lý Phật giáo.","intro":"AN 4.125 liên hệ đến việc tu tập các tâm vô lượng (brahmavihāra) trong truyền thống Pāli.","source":"https://suttacentral.net/an4.125","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","AN 4.125 liên hệ đến việc tu tập các tâm vô lượng (brahmavihāra) trong truyền thống Pāli."],["Nội dung và ý nghĩa","Bốn phẩm chất này nuôi dưỡng lòng thương, sự vui theo niềm vui người khác và thái độ quân bình."],["Gợi ý đọc và thực hành","Chọn một người để thực tập gửi lời chúc an vui, rồi quan sát phản ứng của mình."]]},{"id":"vo-thuong-tuong","name":"Kinh Vô Thường","pali":"SN 22.12 · Kinh văn","tag":"Kinh văn","group":"nguyen-thuy","topics":["nguyen-thuy","nen-tang"],"image":"assets/sutra-niem-xu.jpg","short":"Quán sát sự vô thường của các uẩn và sự không chắc bền.","intro":"Kinh SN 22.12 là một trong những bài kinh ngắn của Tương Ưng Uẩn bàn về sự vô thường.","source":"https://suttacentral.net/sn22.12","sourceLabel":"SuttaCentral – kinh văn","kind":"kinh","sections":[["Giới thiệu về bài kinh","Kinh SN 22.12 là một trong những bài kinh ngắn của Tương Ưng Uẩn bàn về sự vô thường."],["Nội dung và ý nghĩa","Giúp nhận diện cảm giác, suy nghĩ và thân thể luôn thay đổi theo nhân duyên."],["Gợi ý đọc và thực hành","Khi có xúc cảm mạnh, nhắc mình rằng trạng thái này sẽ chuyển biến."]]},{"id":"truong-bo","name":"Trường Bộ Kinh (Dīgha Nikāya)","pali":"DN · Bộ sưu tập","tag":"Bộ sưu tập","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-chuyen-phap-luan.jpg","short":"Tuyển tập các bài kinh dài trong hệ thống kinh tạng Pāli.","intro":"Trường Bộ Kinh (Dīgha Nikāya) là một trong năm bộ Nikāya, gồm nhiều bài kinh dài về đạo đức, tu học và các cuộc đối thoại. Đây là một bộ sưu tập chứ không phải một bài kinh đơn lẻ.","source":"https://suttacentral.net/dn","sourceLabel":"SuttaCentral – kinh văn","kind":"bo","sections":[["Giới thiệu về bài nghi thức","Trường Bộ Kinh (Dīgha Nikāya) là một trong năm bộ Nikāya, gồm nhiều bài kinh dài về đạo đức, tu học và các cuộc đối thoại. Đây là một bộ sưu tập chứ không phải một bài kinh đơn lẻ."],["Nội dung và ý nghĩa","Nhiều chủ đề từ đời sống cư sĩ, giới hạnh đến các giáo lý quan trọng được trình bày có bối cảnh."],["Gợi ý đọc và thực hành","Bắt đầu với DN 2, DN 16 hoặc DN 31 rồi tìm hiểu dần theo mục lục."]]},{"id":"trung-bo","name":"Trung Bộ Kinh (Majjhima Nikāya)","pali":"MN · Bộ sưu tập","tag":"Bộ sưu tập","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-hoi-tho.jpg","short":"Tuyển tập 152 bài kinh trung bình về con đường tu học.","intro":"Trung Bộ Kinh gồm 152 bài kinh thuộc Kinh tạng Pāli, phong phú về giáo lý và phương pháp thực tập. Đây là bộ kinh, không phải bài kinh độc lập.","source":"https://suttacentral.net/mn","sourceLabel":"SuttaCentral – kinh văn","kind":"bo","sections":[["Giới thiệu về bài nghi thức","Trung Bộ Kinh gồm 152 bài kinh thuộc Kinh tạng Pāli, phong phú về giáo lý và phương pháp thực tập. Đây là bộ kinh, không phải bài kinh độc lập."],["Nội dung và ý nghĩa","Dễ bắt đầu từ các bài kinh quán hơi thở, lời dạy cho La-hầu-la và những câu chuyện giáo lý."],["Gợi ý đọc và thực hành","Chọn một bài kinh mỗi tuần; ghi lại điều chưa hiểu để tra cứu thêm."]]},{"id":"tuong-ung-bo","name":"Tương Ưng Bộ Kinh (Saṁyutta Nikāya)","pali":"SN · Bộ sưu tập","tag":"Bộ sưu tập","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-niem-xu.jpg","short":"Tuyển tập kinh được nhóm theo các chủ đề giáo lý.","intro":"Tương Ưng Bộ gồm nhiều bài kinh ngắn được kết nối theo chủ đề như uẩn, duyên khởi, các căn và Tứ Diệu Đế.","source":"https://suttacentral.net/sn","sourceLabel":"SuttaCentral – kinh văn","kind":"bo","sections":[["Giới thiệu về bài nghi thức","Tương Ưng Bộ gồm nhiều bài kinh ngắn được kết nối theo chủ đề như uẩn, duyên khởi, các căn và Tứ Diệu Đế."],["Nội dung và ý nghĩa","Phù hợp tra cứu một chủ đề cụ thể và so sánh nhiều bài kinh liên hệ."],["Gợi ý đọc và thực hành","Bắt đầu với SN 22, SN 12 và SN 56 để học các chủ đề căn bản."]]},{"id":"tang-chi-bo","name":"Tăng Chi Bộ Kinh (Aṅguttara Nikāya)","pali":"AN · Bộ sưu tập","tag":"Bộ sưu tập","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-tu-bi.jpg","short":"Các bài kinh được sắp xếp theo số lượng pháp.","intro":"Tăng Chi Bộ Kinh sắp các pháp theo nhóm từ một đến mười một, có nhiều lời khuyên thực tiễn cho cư sĩ và người tu học.","source":"https://suttacentral.net/an","sourceLabel":"SuttaCentral – kinh văn","kind":"bo","sections":[["Giới thiệu về bài nghi thức","Tăng Chi Bộ Kinh sắp các pháp theo nhóm từ một đến mười một, có nhiều lời khuyên thực tiễn cho cư sĩ và người tu học."],["Nội dung và ý nghĩa","Nhiều bài ngắn có thể đọc từng ngày để suy ngẫm."],["Gợi ý đọc và thực hành","Tìm các chủ đề về giới hạnh, tâm từ và tinh tấn theo bộ số."]]},{"id":"tieu-bo","name":"Tiểu Bộ Kinh (Khuddaka Nikāya)","pali":"KN · Bộ sưu tập","tag":"Bộ sưu tập","group":"nguyen-thuy","topics":["nguyen-thuy"],"image":"assets/sutra-hanh-phuc.jpg","short":"Tập hợp nhiều tác phẩm như Kinh Pháp Cú và Kinh Tập.","intro":"Tiểu Bộ là nhóm tác phẩm đa dạng của Kinh tạng Pāli, bao gồm Pháp Cú, Kinh Tập và nhiều tuyển tập kệ, truyện, lời dạy.","source":"https://suttacentral.net/kn","sourceLabel":"SuttaCentral – kinh văn","kind":"bo","sections":[["Giới thiệu về bài nghi thức","Tiểu Bộ là nhóm tác phẩm đa dạng của Kinh tạng Pāli, bao gồm Pháp Cú, Kinh Tập và nhiều tuyển tập kệ, truyện, lời dạy."],["Nội dung và ý nghĩa","Các thể loại giúp người đọc tiếp cận từ bài kệ ngắn đến chuyện kể và lời dạy sâu sắc."],["Gợi ý đọc và thực hành","Bắt đầu từ Pháp Cú và Kinh Tập rồi mở rộng ra các tuyển tập khác."]]}]);
sutras.forEach(s=>{if(!s.topics)s.topics=[s.group];s.image='assets/kinh/'+s.id+'.webp';if(typeof __gioAssets!=='undefined')s.image=__gioAssets[s.image]||s.image;if(!s.kind)s.kind='kinh';if(!s.intro)s.intro=s.sections[0]?.slice(1).join(' ')||s.short;if(!s.sourceLabel)s.sourceLabel=s.source.includes('suttacentral.net')?'SuttaCentral – kinh văn':'Nguồn đối chiếu';});
