const storeKey='giolanh_saved_sutras';let saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem(storeKey)||'[]'))}catch(e){}
let activeFilter='all',query='',currentSutra=null,heroIndex=0,heroTimer=null,toastTimer=null,scrollRestore=null;
function showToast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500)}
function persistSaved(){try{localStorage.setItem(storeKey,JSON.stringify([...saved]))}catch(e){}}
