function safeHTML(x){return String(x).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function searchClean(text){return String(text).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase()}
function sourceButtonLabel(s){
 if(s.kind==='chu') return 'Xem chú văn ↗';
 if(s.kind==='bo') return 'Mở bộ kinh ↗';
 if(s.kind==='nghi') return 'Nguồn tham khảo ↗';
 return /^https:\/\/(?:suttacentral\.net|cbetaonline\.dila\.edu\.tw)\/.+/.test(s.source) ? 'Đọc kinh văn ↗' : 'Tra cứu kinh văn ↗';
}
function hasText(s){return !!(window.GioKinhRegistry&&window.GioKinhRegistry.link[s.id])}
function cardHTML(s){
 const isSaved=saved.has(s.id),full=hasText(s);
 return `<article class="sutra-card reveal visible"><div class="sutra-cover"><img src="${s.image}" alt="Hình minh họa cho ${safeHTML(s.name)}" loading="lazy"><button type="button" class="sutra-cover-button" data-read="${s.id}" aria-label="Xem giới thiệu ${safeHTML(s.name)}"></button><span class="sutra-badge">${safeHTML(s.tag)}</span>${full?'<span class="sutra-fulltext" title="Có toàn văn tiếng Việt">✦ Toàn văn</span>':''}</div><div class="sutra-card-body"><div class="sutra-card-meta">${safeHTML(s.pali)}</div><h3><button type="button" data-read="${s.id}" class="sutra-title-button">${safeHTML(s.name)}</button></h3><p>${safeHTML(s.short)}</p><div class="sutra-card-actions">${full?`<button type="button" class="sutra-read-full" data-gk-read="${s.id}" aria-label="Đọc toàn văn ${safeHTML(s.name)}">📖 Đọc kinh văn</button><button type="button" class="sutra-read" data-read="${s.id}" aria-label="Xem giới thiệu bài ${safeHTML(s.name)}">Giới thiệu</button>`:`<button type="button" class="sutra-read" data-read="${s.id}" aria-label="Xem giới thiệu bài ${safeHTML(s.name)}">📖 Xem giới thiệu</button><a class="sutra-source-link" href="${safeHTML(s.source)}" target="_blank" rel="noopener noreferrer" aria-label="${safeHTML(sourceButtonLabel(s))}: ${safeHTML(s.name)}">${sourceButtonLabel(s)}</a>`}<button type="button" class="sutra-save ${isSaved?'saved':''}" data-save="${s.id}" aria-label="${isSaved?'Bỏ lưu':'Lưu'} ${safeHTML(s.name)}" title="${isSaved?'Bỏ lưu':'Lưu mục này'}">${isSaved?'♥':'♡'}</button></div></div></article>`;
}
function filteredSutras(){return sutras.filter(s=>(activeFilter==='all'||(activeFilter==='saved'?saved.has(s.id):(s.topics||[s.group]).includes(activeFilter)))&&searchClean([s.name,s.pali,s.short,s.intro,s.tag,...(s.topics||[])].join(' ')).includes(searchClean(query)))}
function renderCards(reset=false){if(!$('#sutraGrid'))return;if(reset)visibleCount=LIB_PAGE_SIZE;const all=filteredSutras(),items=all.slice(0,visibleCount);$('#sutraGrid').innerHTML=items.map(cardHTML).join('') || '<div class="library-empty">Không tìm thấy bài phù hợp. Thử từ khóa ngắn hơn hoặc chọn “Tất cả”.</div>';
$('#resultsNote').textContent=`Hiển thị ${items.length}/${all.length} mục`;const more=$('#libraryMore');more.hidden=items.length===all.length;more.textContent=`Xem thêm ${Math.min(LIB_PAGE_SIZE,all.length-items.length)} mục ↓`;}
function rememberRead(){if(!currentSutra)return;const c=$('#readerScroll');const fraction=Math.max(0,Math.min(1,c.scrollTop/Math.max(1,c.scrollHeight-c.clientHeight)));lastRead={id:currentSutra.id,p:fraction,time:Date.now()};try{localStorage.setItem(readingKey,JSON.stringify(lastRead))}catch(e){}updateContinueReading();}
function updateContinueReading(){const el=$('#continueReading');if(!el)return;if(!lastRead){el.hidden=true;return;}const s=sutras.find(x=>x.id===lastRead.id);if(!s){el.hidden=true;return;}el.hidden=false;$('#continueTitle').textContent=s.name;$('#continuePosition').textContent=`Đã đọc khoảng ${Math.round((lastRead.p||0)*100)}%`;}
function readerApply(){const panel=$('#sutraModal');panel.style.setProperty('--reader-font-size',readerSize+'px');panel.classList.toggle('reader-night',readerDark);$('#readerFontValue').textContent=readerSize+'px';$('#readerNight').textContent=readerDark?'☀':'☾';$('#readerNight').setAttribute('aria-label',readerDark?'Tắt chế độ đọc ban đêm':'Bật chế độ đọc ban đêm');}
function readerProgress(){if($('#sutraModal').hidden)return;const c=$('#readerScroll');const p=Math.max(0,Math.min(1,c.scrollTop/Math.max(1,c.scrollHeight-c.clientHeight)));$('#readerProgressFill').style.width=(p*100).toFixed(1)+'%';$('#readerProgressText').textContent=`${Math.round(p*100)}% đã đọc`;}
function showSutra(id,resume=false){const s=sutras.find(x=>x.id===id);if(!s)return;
currentSutra=s;$('#modalImage').src=s.image;$('#modalImage').alt=`Minh họa ${s.name}`;$('#modalCategory').textContent=s.tag.toUpperCase();$('#modalTitle').textContent=s.name;$('#modalSubtitle').textContent=s.pali;
const headings=s.sections.map(([heading])=>heading);
$('#modalContent').innerHTML=`<nav class="reader-toc" aria-label="Mục lục bài viết"><strong>Mục lục nội dung</strong>${headings.map((heading,i)=>`<a href="#reader-sec-${i}" data-reader-section="${i}">${String(i+1).padStart(2,'0')}. ${safeHTML(heading)}</a>`).join('')}</nav><div class="reader-prose" id="readerProse">${s.sections.map(([heading,...paras],i)=>`<section id="reader-sec-${i}" class="modal-content-section"><h3>${safeHTML(heading)}</h3>${paras.map(p=>`<p>${safeHTML(p)}</p>`).join('')}</section>`).join('')}</div>`;
$('#modalSource').href=s.source;$('#modalSource').textContent=s.kind==='kinh'?'Đọc bản nguồn / đối chiếu ↗':s.kind==='chu'?'Tra cứu chú / kinh bản nguồn ↗':s.kind==='bo'?'Xem mục lục bộ kinh ↗':'Đọc nguồn tham khảo ↗';
const full=hasText(s),src=$('#modalSource'),info=$('#modalInfo');
if(full){const b=window.GioKinhRegistry.books[window.GioKinhRegistry.link[s.id][0]];src.href='#doc-kinh';src.dataset.gkRead=s.id;src.removeAttribute('target');src.textContent='📖 Đọc toàn văn trên Gió Lành';
 $('#modalSourceFoot').href=b?b.src:s.source;$('#modalSourceFoot').textContent=b?b.srcName+' · '+b.title:'SuttaCentral';
 if(info)info.textContent='Đây là phần giới thiệu do Gió Lành biên soạn. Toàn văn kinh tiếng Việt đã có sẵn — bấm “Đọc toàn văn” để mở như một cuốn sách.';}
else{delete src.dataset.gkRead;src.target='_blank';$('#modalSourceFoot').href=s.source;$('#modalSourceFoot').textContent=s.sourceLabel||new URL(s.source).hostname;
 if(info)info.textContent='Đây là phần giới thiệu do Gió Lành biên soạn. Gió Lành chưa có bản Việt dịch được xác minh nguồn cho mục này; hãy dùng nút nguồn để đối chiếu kinh văn.';}
$('#saveButton').textContent=saved.has(s.id)?'♥ Đã lưu':'♡ Lưu mục này';$('#listenButton').textContent='♫ Nghe phần giới thiệu';
$('#readerScroll').scrollTop=0;readerApply();openModal($('#sutraModal'));
const canResume=lastRead?.id===id&&lastRead.p>.04;$('#readerResume').hidden=!canResume;
if(resume&&canResume){requestAnimationFrame(()=>{const c=$('#readerScroll');c.scrollTop=(lastRead.p||0)*(c.scrollHeight-c.clientHeight);readerProgress();});}
else readerProgress();
}
function openModal(el){scrollRestore=document.activeElement;el.hidden=false;document.body.classList.add('modal-open');$('.modal-close',el)?.focus()}
function closeModal(el){if(el.id==='sutraModal'){rememberRead();}window.GioLanhMedia?.stopSpeech();el.hidden=true;document.body.classList.remove('modal-open');scrollRestore?.focus?.()}
function toggleSaved(id){if(saved.has(id)){saved.delete(id);showToast('Đã bỏ lưu bài kinh.')}else{saved.add(id);showToast('Đã lưu bài kinh trên trình duyệt này.')}persistSaved();renderCards();if(currentSutra?.id===id)$('#saveButton').textContent=saved.has(id)?'♥ Đã lưu':'♡ Lưu bài kinh'}
// Hero slideshow, automatic crossfades only.
function setHero(index){heroIndex=(index+heroMessages.length)%heroMessages.length;$$('.hero-slide').forEach((slide,i)=>{slide.classList.toggle('active',i===heroIndex);slide.setAttribute('aria-hidden',i===heroIndex?'false':'true')});$$('#heroDots button').forEach((b,i)=>{b.classList.toggle('active',i===heroIndex);b.setAttribute('aria-selected',i===heroIndex?'true':'false')});const h=$('#heroTitle'),d=$('#heroDescription');h.style.opacity='.15';d.style.opacity='.15';setTimeout(()=>{h.innerHTML=heroMessages[heroIndex].title;d.textContent=heroMessages[heroIndex].desc;h.style.opacity='1';d.style.opacity='1'},140)}
function restartHero(){clearInterval(heroTimer);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)heroTimer=setInterval(()=>setHero(heroIndex+1),6500)}
$('#heroTitle').style.transition='opacity .25s';$('#heroDescription').style.transition='opacity .25s';restartHero();
// Navigation and search.
const menuToggle=$('#menuToggle');menuToggle.addEventListener('click',()=>{const nav=$('#mobileNav');nav.hidden=!nav.hidden;menuToggle.setAttribute('aria-expanded',String(!nav.hidden))});$$('#mobileNav a').forEach(a=>a.addEventListener('click',()=>{$('#mobileNav').hidden=true;menuToggle.setAttribute('aria-expanded','false')}));$('#openSearch').addEventListener('click',()=>{$('#searchPanel').hidden=!$('#searchPanel').hidden;if(!$('#searchPanel').hidden)$('#globalSearch').focus()});
function quickMatches(q){const n=searchClean(q.trim());if(n.length<2)return[];return sutras.filter(s=>hasText(s)&&searchClean([s.name,s.pali,s.tag,s.short].join(' ')).includes(n)).slice(0,8)}
function renderQuick(){const q=$('#globalSearch').value,list=$('#globalResults'),hits=quickMatches(q);
 list.innerHTML=hits.length?hits.map(s=>`<li><button type="button" data-gk-read="${s.id}"><strong>${safeHTML(s.name)}</strong><span>${safeHTML(s.pali)}</span></button></li>`).join(''):(searchClean(q.trim()).length>=2?'<li class="gk-quick-empty">Chưa có kinh văn phù hợp. Thử từ khóa khác, ví dụ: Địa Tạng, Đại Bi, Từ Bi…</li>':'')}
$('#globalSearch').addEventListener('input',renderQuick);
function executeSearch(){const first=quickMatches($('#globalSearch').value)[0];if(first){$('#searchPanel').hidden=true;window.GioReader?.openFor(first.id)}else renderQuick()}
$('#searchSubmit').addEventListener('click',executeSearch);$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter')executeSearch()});
$('#globalResults').addEventListener('click',e=>{if(e.target.closest('[data-gk-read]'))$('#searchPanel').hidden=true});
$$('#sutraFilters button').forEach(b=>b.addEventListener('click',()=>{activeFilter=b.dataset.filter;$$('#sutraFilters button').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});renderCards(true)}));
$('#sutraGrid')?.addEventListener('click',e=>{const read=e.target.closest('[data-read]'),save=e.target.closest('[data-save]');if(read)showSutra(read.dataset.read);if(save)toggleSaved(save.dataset.save)});renderCards();
$('#modalClose').addEventListener('click',()=>closeModal($('#sutraModal')));$('[data-close-modal]').addEventListener('click',()=>closeModal($('#sutraModal')));$('#saveButton').addEventListener('click',()=>currentSutra&&toggleSaved(currentSutra.id));
$('#listenButton').addEventListener('click',()=>{if(currentSutra && window.GioLanhMedia)window.GioLanhMedia.playSutra(currentSutra.id)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#sutraModal').hidden)closeModal($('#sutraModal'));if(!$('#exerciseModal').hidden)closeModal($('#exerciseModal'));$('#searchPanel').hidden=true}});
// Practice prompts.
const exerciseContents={kindness:{title:'Gửi một lời từ ái',text:'Ngồi thoải mái và nhắm mắt nếu thấy dễ chịu.\n\nNhẹ nhàng thầm nhắc: “Mong tôi được bình an. Mong tôi được khỏe mạnh. Mong tôi được sống với tâm nhẹ nhàng.”\n\nTiếp tục gửi lời chúc đó đến một người bạn thương và dần mở rộng đến những người bạn gặp mỗi ngày.'},gratitude:{title:'Biết ơn những điều bình dị',text:'Hít vào chậm, thở ra nhẹ.\n\nHãy nhớ lại ba điều nhỏ làm bạn thấy ấm lòng hôm nay: một bữa cơm, một lời hỏi thăm, một khoảng trời yên tĩnh.\n\nKhông cần điều gì đặc biệt — chỉ cần nhận ra những điều lành đã có mặt.'}};
$$('[data-exercise]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.exercise;if(id==='breath'){$('#breathCircle').scrollIntoView({behavior:'smooth',block:'center'});$('#breathButton').focus();return}const ex=exerciseContents[id];$('#exerciseTitle').textContent=ex.title;$('#exerciseText').textContent=ex.text;openModal($('#exerciseModal'))}));$('#exerciseClose').addEventListener('click',()=>closeModal($('#exerciseModal')));$('[data-close-exercise]').addEventListener('click',()=>closeModal($('#exerciseModal')));$('#exerciseGo').addEventListener('click',()=>closeModal($('#exerciseModal')));
// Breath timer. Gentle 4 s inhale, 4 s rest, 6 s exhale; users may stop at any time.
let breathInterval=null,remaining=60,breathTick=0;const formatTime=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');const breathDuration=$('#breathDuration'),breathCounter=$('#breathCounter'),breathCircle=$('#breathCircle'),breathPhase=$('#breathPhase'),breathButton=$('#breathButton');
function updateBreathDisplay(){breathCounter.textContent=formatTime(remaining);const phase=breathTick%14;const label=phase<4?'Hít vào':phase<8?'Giữ nhẹ':'Thở ra';breathPhase.textContent=label;breathCircle.classList.toggle('inhale',phase<4);breathCircle.classList.toggle('exhale',phase>=8);$('#breathGuide').textContent=label==='Hít vào'?'Hít vào tự nhiên, cảm nhận không khí đi vào.':label==='Giữ nhẹ'?'Giữ nhẹ nếu thấy thoải mái; không gắng sức.':'Thở ra thư thái, để vai và gương mặt mềm lại.'}
function stopBreath(done=false){clearInterval(breathInterval);breathInterval=null;breathButton.textContent='Bắt đầu';breathDuration.disabled=false;breathCircle.classList.remove('inhale','exhale');breathPhase.textContent=done?'Thật an lành':'An nhiên';if(done){showToast('Bạn đã hoàn thành một khoảng lặng cho chính mình. 🌿');$('#breathGuide').textContent='Cảm ơn bạn đã dành thời gian trở về với chính mình.'}else{$('#breathGuide').textContent='Bấm bắt đầu, hít vào nhẹ nhàng và thở ra thật chậm.'}}
breathDuration.addEventListener('change',()=>{if(!breathInterval){remaining=Number(breathDuration.value);breathCounter.textContent=formatTime(remaining)}});breathButton.addEventListener('click',()=>{if(breathInterval){stopBreath();remaining=Number(breathDuration.value);breathCounter.textContent=formatTime(remaining);return}remaining=Number(breathDuration.value);breathTick=0;breathButton.textContent='Dừng lại';breathDuration.disabled=true;updateBreathDisplay();breathInterval=setInterval(()=>{remaining--;breathTick++;if(remaining<=0){remaining=0;breathCounter.textContent='00:00';stopBreath(true);return}updateBreathDisplay()},1000)});
// Image gallery carousel.
let galleryIndex=0;const galleryItems=$$('#galleryTrack figure');function updateGallery(){const gap=parseFloat(getComputedStyle($('#galleryTrack')).gap)||20;const w=galleryItems[0].getBoundingClientRect().width;const visible=window.innerWidth<=650?1:window.innerWidth<=960?2:3;const max=Math.max(0,galleryItems.length-visible);galleryIndex=Math.max(0,Math.min(max,galleryIndex));$('#galleryTrack').style.transform=`translateX(-${galleryIndex*(w+gap)}px)`}$('#galleryPrev').addEventListener('click',()=>{galleryIndex--;updateGallery()});$('#galleryNext').addEventListener('click',()=>{const visible=window.innerWidth<=650?1:window.innerWidth<=960?2:3;galleryIndex=galleryIndex>=galleryItems.length-visible?0:galleryIndex+1;updateGallery()});window.addEventListener('resize',updateGallery);updateGallery();
// Reveal-on-scroll and utility interactions.
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}})},{threshold:.09});$$('.reveal').forEach(el=>observer.observe(el))}else{$$('.reveal').forEach(el=>el.classList.add('visible'))}
window.addEventListener('scroll',()=>{const scrolled=window.scrollY>110;$('.site-header').classList.toggle('is-scrolled',scrolled);$('#backToTop').classList.toggle('show',window.scrollY>600)},{passive:true});$('#backToTop').addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));if($('#newsletterForm'))$('#newsletterForm').addEventListener('submit',e=>{e.preventDefault();showToast('Chức năng đăng ký email chưa được kích hoạt.');$('#newsletterForm').reset()});

// Responsive reading experience: font size, dark mode, progress and resume.
$('#librarySearch')?.addEventListener('input',e=>{query=e.target.value.trim();renderCards(true)});
$('#libraryClear')?.addEventListener('click',()=>{$('#librarySearch').value='';$('#globalSearch').value='';query='';renderCards(true);$('#librarySearch').focus()});
$('#libraryMore')?.addEventListener('click',()=>{visibleCount+=LIB_PAGE_SIZE;renderCards();});
$('#readerBigger').addEventListener('click',()=>{readerSize=Math.min(26,readerSize+2);try{localStorage.setItem('giolanh_reader_size_v3',String(readerSize))}catch(e){}readerApply()});
$('#readerSmaller').addEventListener('click',()=>{readerSize=Math.max(16,readerSize-2);try{localStorage.setItem('giolanh_reader_size_v3',String(readerSize))}catch(e){}readerApply()});
$('#readerNight').addEventListener('click',()=>{readerDark=!readerDark;try{localStorage.setItem('giolanh_reader_night_v3',readerDark?'1':'0')}catch(e){}readerApply()});
$('#readerResume').addEventListener('click',()=>{const c=$('#readerScroll');if(lastRead?.id===currentSutra?.id){c.scrollTo({top:(lastRead.p||0)*(c.scrollHeight-c.clientHeight),behavior:'smooth'});}});
$('#readerScroll').addEventListener('scroll',()=>{readerProgress();if(currentSutra){clearTimeout(window.__gioReaderSave);window.__gioReaderSave=setTimeout(rememberRead,300)}},{passive:true});
$('#continueButton')?.addEventListener('click',()=>{if(lastRead)showSutra(lastRead.id,true)});
$('#modalContent').addEventListener('click',e=>{const a=e.target.closest('[data-reader-section]');if(!a)return;e.preventDefault();const target=$('#reader-sec-'+a.dataset.readerSection);if(!target)return;const c=$('#readerScroll');c.scrollTo({top:target.getBoundingClientRect().top-c.getBoundingClientRect().top+c.scrollTop-14,behavior:'smooth'});});
readerApply();updateContinueReading();
